const QUESTIONS = [

// ====================== DOMAIN 1 ======================
{d:1,e:"medium",s:"Which of the following is a preventive control?",o:["Firewall blocking unauthorised traffic","Security camera recording an incident","Restoring from backup after an attack","A warning poster"],c:0,x:"Un firewall qui bloque le trafic est un contrôle préventif.",r:"Une caméra est un contrôle détectif."},
{d:1,e:"medium",s:"What does the 'C' in the CIA triad stand for?",o:["Compliance","Confidentiality","Control","Certification"],c:1,x:"C = Confidentiality (Confidentialité).",r:"Ce n'est pas Compliance."},
{d:1,e:"medium",s:"A password is an example of which authentication factor?",o:["Something you have","Something you are","Something you know","Somewhere you are"],c:2,x:"Un mot de passe est 'something you know'.",r:"Une empreinte est 'something you are'."},

{d:1,e:"hard",s:"Which principle requires that users only receive the minimum permissions necessary?",o:["Separation of duties","Least privilege","Need to know","Defense in depth"],c:1,x:"Le moindre privilège limite les permissions au strict nécessaire.",r:"La séparation des tâches divise les responsabilités."},
{d:1,e:"hard",s:"Requiring two different people to approve a critical change is an application of:",o:["Least privilege","Need to know","Separation of duties","Defense in depth"],c:2,x:"Exiger deux personnes applique la séparation des tâches.",r:"Le moindre privilège limite les droits d'une seule personne."},
{d:1,e:"hard",s:"A system that denies all access when it cannot evaluate its security policy is said to:",o:["Fail open","Fail closed (fail secure)","Fail safe for availability","Gracefully degrade"],c:1,x:"Fail closed signifie que le système refuse l'accès en cas de problème.",r:"Fail open autorise l'accès par défaut."},
{d:1,e:"hard",s:"Which control type is primarily intended to identify that a security event has occurred?",o:["Preventive","Deterrent","Detective","Corrective"],c:2,x:"Les contrôles détectifs identifient qu'un événement s'est produit.",r:"Les contrôles préventifs cherchent à l'empêcher."},
{d:1,e:"hard",s:"Buying cyber insurance is an example of which risk treatment strategy?",o:["Risk avoidance","Risk mitigation","Risk transference","Risk acceptance"],c:2,x:"L'assurance est une forme de transfert de risque.",r:"La mitigation réduit le risque par des contrôles."},
{d:1,e:"hard",s:"Which property of a secure hash function makes it difficult to find two different inputs that produce the same output?",o:["Preimage resistance","Avalanche effect","Collision resistance","Determinism"],c:2,x:"La résistance aux collisions empêche de trouver deux entrées avec le même hash.",r:"La résistance à la préimage empêche de retrouver l'entrée."},

{d:1,e:"really-hard",s:"In a Zero Trust architecture, which element is continuously evaluated on every request?",o:["User identity, device posture and contextual risk signals","Only the user’s password at login","Only the source IP address","Only the time of day"],c:0,x:"Zero Trust évalue en continu l'identité, la posture et le contexte à chaque requête.",r:"Une authentification unique au login n'est pas suffisante."},
{d:1,e:"really-hard",s:"Which principle is MOST directly violated when one person can both approve and execute a high-value financial transfer?",o:["Least privilege","Defense in depth","Separation of duties","Need to know"],c:2,x:"La séparation des tâches exige que des personnes différentes approuvent et exécutent les actions critiques.",r:"Le moindre privilège ne force pas la dualité des rôles."},
{d:1,e:"really-hard",s:"A system is designed to deny all access when its policy engine is unavailable. This decision prioritises which security objective?",o:["Availability over everything else","Performance over security","Confidentiality and integrity over availability","User convenience over risk"],c:2,x:"Fail closed privilégie la confidentialité et l'intégrité au détriment de la disponibilité.",r:"Fail open privilégierait la disponibilité."},

// ===== DOMAIN 1 – 40 NEW QUESTIONS =====

{d:1,e:"medium",s:"Which of the following best describes a deterrent control?",o:["A firewall rule that blocks traffic","A security camera visible to potential attackers","A backup system that restores data","An intrusion detection system that alerts"],c:1,x:"Un contrôle dissuasif vise à décourager l'attaquant avant qu'il n'agisse (ex: caméra visible).",r:"Un firewall est plutôt préventif."},
{d:1,e:"medium",s:"What is the main purpose of the principle of least privilege?",o:["To give users maximum access for convenience","To limit user permissions to only what is required for their job","To remove all access controls","To allow users to share accounts freely"],c:1,x:"Le moindre privilège limite les permissions au strict nécessaire pour le poste.",r:"Donner le maximum d'accès augmente les risques."},
{d:1,e:"medium",s:"Which authentication factor is based on a physical characteristic?",o:["Something you know","Something you have","Something you are","Somewhere you are"],c:2,x:"Something you are correspond aux biométries (empreinte, visage, etc.).",r:"Something you know = mot de passe."},
{d:1,e:"medium",s:"A control that identifies a security incident after it has occurred is called:",o:["Preventive","Detective","Deterrent","Compensating"],c:1,x:"Les contrôles détectifs repèrent les incidents après qu'ils se soient produits.",r:"Les contrôles préventifs agissent avant."},
{d:1,e:"medium",s:"Which of the following is an example of a technical control?",o:["Security awareness training","Firewall rules","Security policy document","Background checks"],c:1,x:"Un firewall est un contrôle technique.",r:"La formation est un contrôle administratif."},

{d:1,e:"hard",s:"Which principle is applied when two people are required to complete a critical financial transaction?",o:["Least privilege","Defense in depth","Separation of duties","Need to know"],c:2,x:"La séparation des tâches exige que plusieurs personnes soient impliquées dans les actions critiques.",r:"Le moindre privilège limite les droits d'une seule personne."},
{d:1,e:"hard",s:"When a system is designed to deny access if it cannot determine the correct security decision, it is said to:",o:["Fail open","Fail closed","Fail safe for availability","Fail soft"],c:1,x:"Fail closed signifie que le système refuse l'accès en cas d'incertitude.",r:"Fail open autorise l'accès par défaut."},
{d:1,e:"hard",s:"Which property of a cryptographic hash function ensures that a small change in input produces a large change in output?",o:["Collision resistance","Preimage resistance","Avalanche effect","Determinism"],c:2,x:"L'effet d'avalanche fait qu'un petit changement d'entrée change fortement le hash.",r:"La résistance aux collisions empêche de trouver deux entrées identiques."},
{d:1,e:"hard",s:"Digital signatures primarily provide which security services?",o:["Confidentiality and availability","Integrity and non-repudiation","Availability and authentication","Confidentiality only"],c:1,x:"Les signatures numériques fournissent l'intégrité et la non-répudiation.",r:"Elles ne chiffrent pas les données (confidentialité)."},
{d:1,e:"hard",s:"Which of the following best describes defense in depth?",o:["Using a single very strong control","Using multiple layers of security controls","Removing all unnecessary controls","Relying only on perimeter security"],c:1,x:"La défense en profondeur consiste à superposer plusieurs couches de contrôles.",r:"Une seule couche est insuffisante."},
{d:1,e:"hard",s:"A company requires that access to sensitive data is granted only to those who have a legitimate business need. This is an example of:",o:["Least privilege","Need to know","Separation of duties","Defense in depth"],c:1,x:"Need to know limite l'accès à l'information selon le besoin professionnel réel.",r:"Le moindre privilège est plus large et s'applique aussi aux actions."},
{d:1,e:"hard",s:"Which type of control is a security awareness training program primarily considered?",o:["Technical","Physical","Administrative","Compensating"],c:2,x:"La sensibilisation est un contrôle administratif / managérial.",r:"Ce n'est pas un contrôle technique."},
{d:1,e:"hard",s:"Purchasing cyber insurance is an example of which risk treatment approach?",o:["Risk avoidance","Risk mitigation","Risk transference","Risk acceptance"],c:2,x:"L'assurance est une forme de transfert de risque.",r:"La mitigation réduit le risque par des contrôles."},
{d:1,e:"hard",s:"Which access control model uses security labels and mandatory rules that users cannot change?",o:["Discretionary Access Control (DAC)","Role-Based Access Control (RBAC)","Mandatory Access Control (MAC)","Attribute-Based Access Control (ABAC)"],c:2,x:"Le MAC utilise des labels et des règles obligatoires non modifiables par les utilisateurs.",r:"Le DAC laisse le propriétaire de l'objet décider."},
{d:1,e:"hard",s:"What is the primary goal of implementing least privilege for service accounts?",o:["Make administration easier","Limit the potential damage if the account is compromised","Eliminate the need for monitoring","Allow the account to perform any action"],c:1,x:"Limiter les droits des comptes de service réduit l'impact d'une compromission.",r:"Ce n'est pas pour faciliter l'administration."},
{d:1,e:"hard",s:"A control that restores a system to a secure state after an incident is classified as:",o:["Preventive","Detective","Corrective","Deterrent"],c:2,x:"Les contrôles correctifs rétablissent un état sécurisé après un incident.",r:"Les contrôles préventifs agissent avant."},
{d:1,e:"hard",s:"Which concept requires that no single individual has complete control over a critical process?",o:["Least privilege","Need to know","Separation of duties","Defense in depth"],c:2,x:"La séparation des tâches empêche qu'une seule personne contrôle tout un processus critique.",r:"Le moindre privilège limite les droits mais ne divise pas forcément les rôles."},
{d:1,e:"hard",s:"In cryptography, non-repudiation primarily prevents:",o:["Unauthorised reading of data","A party from denying they performed an action","System downtime","Unauthorised modification only"],c:1,x:"La non-répudiation empêche un acteur de nier avoir réalisé une action.",r:"Elle ne protège pas directement la confidentialité."},
{d:1,e:"hard",s:"Which of the following is the best example of a compensating control?",o:["Implementing MFA when a system cannot support it natively by using a third-party solution","Removing a system from the network without business justification","Disabling all logging on a critical system","Accepting a risk without any additional measures"],c:0,x:"Un contrôle compensatoire atténue un risque lorsqu'un contrôle principal ne peut pas être mis en place.",r:"Accepter purement le risque n'est pas un contrôle compensatoire."},
{d:1,e:"hard",s:"What does the principle of least privilege aim to reduce most directly?",o:["The need for authentication","The potential impact of account compromise","The importance of encryption","The requirement for logging"],c:1,x:"Le moindre privilège réduit l'impact potentiel d'une compromission de compte.",r:"Il ne réduit pas le besoin d'authentification."},

{d:1,e:"really-hard",s:"In a Zero Trust model, which traditional security assumption is explicitly rejected?",o:["Trust based on network location (inside vs outside)","The need for strong authentication","The value of encryption at rest and in transit","The importance of continuous monitoring"],c:0,x:"Zero Trust rejette la confiance implicite basée sur la localisation réseau.",r:"L'authentification forte reste un pilier de Zero Trust."},
{d:1,e:"really-hard",s:"Which statement best describes the correct application of least privilege in modern cloud environments?",o:["Privileges should be permanent and broad for efficiency","Privileges should be granted just-in-time and just-enough, then revoked","All users should have administrator rights on their workstations","Service accounts should always have domain-level privileges"],c:1,x:"Dans le cloud moderne, le moindre privilège s'applique de façon dynamique (JIT / just-enough).",r:"Les privilèges permanents élevés sont à éviter."},
{d:1,e:"really-hard",s:"A security architect designs a system that fails closed when the policy decision point is unavailable. This choice primarily supports which security objectives?",o:["Availability over confidentiality and integrity","Confidentiality and integrity over availability","Performance over security","User experience over risk reduction"],c:1,x:"Fail closed privilégie la confidentialité et l'intégrité au détriment de la disponibilité.",r:"Fail open privilégierait la disponibilité."},
{d:1,e:"really-hard",s:"Which metric is most useful for measuring the real effectiveness of a security awareness program over time?",o:["Number of training modules completed","Number of posters displayed in offices","Reduction in successful phishing simulations and human-error incidents","Time spent watching training videos"],c:2,x:"La réduction des clics sur les simulations de phishing et des incidents liés à l'humain est le meilleur indicateur d'efficacité.",r:"Le simple taux de complétion ne mesure pas le changement de comportement."},
{d:1,e:"really-hard",s:"Why is encrypting data at rest alone insufficient for a true Zero Trust data protection strategy?",o:["Encryption automatically provides strong authentication","Access to decryption keys and the context of each request must still be continuously verified","Encryption eliminates the need for any access control","Encryption at rest is the only control required in Zero Trust"],c:1,x:"Même chiffrées, les données nécessitent un contrôle d'accès continu aux clés et au contexte de la requête.",r:"Le chiffrement seul ne constitue pas un Zero Trust complet."},
{d:1,e:"really-hard",s:"Which statement about risk appetite is most accurate?",o:["Risk appetite is determined only after all controls are implemented","Risk appetite defines how much residual risk the organisation is willing to accept and influences control selection","Risk appetite only applies to financial risks, not cyber risks","Risk appetite is identical to risk tolerance in every organisation"],c:1,x:"L'appétit pour le risque définit le niveau de risque résiduel acceptable et guide le choix des contrôles.",r:"Il n'est pas défini après la mise en place des contrôles."},
{d:1,e:"really-hard",s:"In a mature security program, which approach is preferred for granting elevated privileges?",o:["Permanent standing administrator rights for convenience","Shared privileged accounts to reduce the number of accounts","Just-in-time and just-enough access with automatic revocation","No elevated privileges for anyone under any circumstances"],c:2,x:"L'accès juste-à-temps et juste-suffisant est préféré aux privilèges permanents.",r:"Les privilèges permanents élevés augmentent fortement le risque."},
{d:1,e:"really-hard",s:"Which of the following best illustrates the concept of defense in depth?",o:["Relying solely on a next-generation firewall","Using network segmentation, endpoint protection, MFA and monitoring together","Removing all security controls except encryption","Trusting the internal network completely once a user is authenticated"],c:1,x:"La défense en profondeur combine plusieurs types de contrôles sur les mêmes actifs.",r:"Une seule couche de protection est insuffisante."},
{d:1,e:"really-hard",s:"A control that is implemented because a primary control cannot be used is best described as a:",o:["Preventive control","Detective control","Compensating control","Deterrent control"],c:2,x:"Un contrôle compensatoire est mis en place lorsque le contrôle principal ne peut pas être appliqué.",r:"Ce n'est pas simplement un contrôle préventif."},
{d:1,e:"really-hard",s:"Which statement best describes the relationship between policies, standards and procedures?",o:["They are interchangeable terms with the same meaning","Policies set high-level direction, standards define mandatory requirements, procedures provide step-by-step instructions","Procedures are higher level than policies","Standards are always optional while policies are mandatory"],c:1,x:"Les politiques donnent la direction, les standards fixent les exigences, les procédures décrivent les étapes.",r:"Ces termes ne sont pas interchangeables."},

{d:1,e:"medium",s:"Which of the following is considered an administrative control?",o:["Intrusion prevention system","Security policy","Door access badge reader","Disk encryption"],c:1,x:"Une politique de sécurité est un contrôle administratif.",r:"Un IPS est un contrôle technique."},
{d:1,e:"medium",s:"What is the primary purpose of non-repudiation?",o:["To encrypt data","To prevent a party from denying they performed an action","To increase system availability","To hide the identity of the sender"],c:1,x:"La non-répudiation empêche un acteur de nier avoir réalisé une action.",r:"Elle ne sert pas à chiffrer les données."},
{d:1,e:"hard",s:"Which of the following is the best example of a physical control?",o:["Security awareness training","Firewall rule set","Locked server room door","Password complexity policy"],c:2,x:"Une porte verrouillée de salle serveur est un contrôle physique.",r:"Une formation est un contrôle administratif."},
{d:1,e:"hard",s:"When an organisation decides not to implement a control because the cost outweighs the benefit, this is an example of:",o:["Risk avoidance","Risk mitigation","Risk transference","Informed risk acceptance"],c:3,x:"Lorsque le coût du contrôle dépasse le bénéfice attendu, l'organisation peut accepter le risque de façon informée.",r:"Ce n'est pas de l'évitement du risque."},
{d:1,e:"hard",s:"Which security concept is most closely associated with the use of security labels on data and mandatory access rules?",o:["Discretionary Access Control","Role-Based Access Control","Mandatory Access Control","Rule-Based Access Control only"],c:2,x:"Le MAC s'appuie sur des labels de sécurité et des règles obligatoires.",r:"Le DAC laisse le propriétaire décider."},
{d:1,e:"really-hard",s:"In the context of Zero Trust, what is continuously verified rather than assumed after initial login?",o:["Only the user’s password strength","User identity, device health, and request context","Only the network location of the user","Only the time of the request"],c:1,x:"Zero Trust vérifie en continu l'identité, la santé de l'appareil et le contexte de chaque requête.",r:"Une vérification uniquement au login n'est pas du Zero Trust."},
{d:1,e:"really-hard",s:"Which of the following best demonstrates the principle of separation of duties in a software development environment?",o:["Developers can write and deploy code directly to production","The same person develops, tests and approves changes","Different individuals are responsible for development, testing and production deployment","All developers have full administrator rights on production systems"],c:2,x:"Séparer le développement, les tests et le déploiement en production applique la séparation des tâches.",r:"Permettre à la même personne de tout faire viole ce principe."},
{d:1,e:"hard",s:"A company implements both a firewall and an intrusion detection system for the same network segment. This is an example of:",o:["Single point of failure","Defense in depth","Risk avoidance","Least privilege"],c:1,x:"Combiner firewall (préventif) et IDS (détectif) illustre la défense en profondeur.",r:"Ce n'est pas un single point of failure."},
{d:1,e:"medium",s:"Which of the following is an example of 'something you have'?",o:["Password","Fingerprint","Smart card or hardware token","PIN code"],c:2,x:"Une smart card ou un token matériel est 'something you have'.",r:"Un mot de passe est 'something you know'."},
{d:1,e:"hard",s:"What is the main security benefit of using mutual TLS (mTLS) between services?",o:["It only encrypts data in one direction","It provides cryptographic mutual authentication of both parties","It eliminates the need for any authorization","It automatically scales the application"],c:1,x:"mTLS authentifie mutuellement les deux parties de façon cryptographique.",r:"Il ne se contente pas de chiffrer dans un seul sens."},

// ====================== DOMAIN 2 ======================
{d:2,e:"medium",s:"What type of attack floods a system with traffic to make it unavailable?",o:["Denial of Service (DoS/DDoS)","Phishing","SQL injection","Man-in-the-middle"],c:0,x:"Les attaques DoS/DDoS saturent un service pour le rendre indisponible.",r:"Le phishing vise à tromper l'utilisateur."},
{d:2,e:"medium",s:"What is the main goal of a phishing attack?",o:["Encrypt files for ransom","Trick users into revealing sensitive information or performing actions","Scan ports on a network","Exploit a buffer overflow"],c:1,x:"Le phishing vise à tromper les utilisateurs pour obtenir des informations ou des actions.",r:"Le ransomware chiffre les fichiers."},
{d:2,e:"medium",s:"Which type of malware encrypts files and demands payment?",o:["Worm","Trojan","Spyware","Ransomware"],c:3,x:"Le ransomware chiffre les fichiers et demande une rançon.",r:"Un ver se propage de manière autonome."},

{d:2,e:"hard",s:"An attacker requests service tickets for high-privilege accounts and cracks them offline. This technique is called:",o:["Kerberoasting","AS-REP roasting","Pass-the-hash","Golden ticket"],c:0,x:"Kerberoasting consiste à demander des TGS puis à les cracker hors ligne.",r:"AS-REP roasting cible les comptes sans pré-authentification."},
{d:2,e:"hard",s:"Which technique targets accounts that do not require Kerberos pre-authentication?",o:["Kerberoasting","Pass-the-ticket","AS-REP roasting","Silver ticket"],c:2,x:"AS-REP roasting cible les comptes avec le flag DONT_REQ_PREAUTH.",r:"Kerberoasting travaille sur les TGS."},
{d:2,e:"hard",s:"Which attack forges a TGT using the KRBTGT hash?",o:["Silver ticket","Kerberoasting","Golden ticket","AS-REP roasting"],c:2,x:"Le Golden Ticket est un TGT forgé avec le hash KRBTGT.",r:"Le Silver Ticket est un TGS forgé avec le hash d'un compte de service."},
{d:2,e:"hard",s:"Which technique allows an attacker to obtain password hashes by simulating domain controller replication?",o:["DCShadow","Golden ticket","DCSync","Kerberoasting"],c:2,x:"DCSync abuse des privilèges de réplication pour récupérer les hashes.",r:"DCShadow injecte des objets via un faux DC."},
{d:2,e:"hard",s:"Using a legitimate system binary to download and execute a payload is an example of:",o:["Traditional dropper","Bootkit","Living-off-the-land (LOLBin) technique","Rootkit only"],c:2,x:"L'utilisation de binaires légitimes est une technique living-off-the-land.",r:"Un dropper traditionnel apporte son propre binaire."},
{d:2,e:"hard",s:"Which vulnerability allows an attacker to make the server send requests to internal or external resources of their choosing?",o:["Cross-site request forgery (CSRF)","XSS","Server-Side Request Forgery (SSRF)","SQL injection"],c:2,x:"SSRF force le serveur à émettre des requêtes vers des ressources choisies par l'attaquant.",r:"CSRF force le navigateur de la victime."},

{d:2,e:"really-hard",s:"An attacker forces a Domain Controller to authenticate to a system they control and relays the authentication to AD CS. This chain is an example of:",o:["Classic Kerberoasting","Simple pass-the-hash","Authentication coercion + NTLM relay (ESC8 style)","AS-REP roasting only"],c:2,x:"Cette chaîne (coercion + relais vers AD CS) est une attaque de type ESC8.",r:"Ce n'est pas du Kerberoasting."},
{d:2,e:"really-hard",s:"An attacker configures msDS-AllowedToActOnBehalfOfOtherIdentity on a high-value server using a compromised computer account. They are preparing:",o:["Classic unconstrained delegation","Kerberoasting","Resource-Based Constrained Delegation (RBCD)","DCSync"],c:2,x:"Configurer msDS-AllowedToActOnBehalfOfOtherIdentity est l'étape clé d'une attaque RBCD.",r:"Ce n'est pas de la délégation non contrainte classique."},
{d:2,e:"really-hard",s:"An attacker has obtained the KRBTGT hash. What is the MOST impactful long-term action they can take?",o:["Create Golden Tickets for persistent domain dominance","Only create one Silver Ticket","Only perform Kerberoasting","Only perform AS-REP roasting"],c:0,x:"Le hash KRBTGT permet de créer des Golden Tickets offrant une persistance très durable.",r:"Les Silver Tickets ne nécessitent pas le hash KRBTGT."},

// ===== DOMAIN 1 – 40 NEW QUESTIONS (Hard + Really Hard) =====

{d:1,e:"hard",s:"Which security control is primarily designed to discourage potential attackers from attempting an action?",o:["Preventive control","Detective control","Deterrent control","Corrective control"],c:2,x:"Les contrôles dissuasifs (deterrent) visent à décourager l'attaquant avant qu'il n'agisse.",r:"Les contrôles préventifs bloquent l'action, les détectifs la repèrent."},
{d:1,e:"hard",s:"A company requires that no single employee can both request and approve a high-value purchase. This is an application of:",o:["Least privilege","Need to know","Separation of duties","Defense in depth"],c:2,x:"Empêcher qu'une seule personne demande et approuve une action critique applique la séparation des tâches.",r:"Le moindre privilège limite les droits d'une personne, mais ne force pas la dualité."},
{d:1,e:"hard",s:"Which property of a cryptographic hash function makes it computationally infeasible to find two different inputs that produce the same hash?",o:["Preimage resistance","Second preimage resistance","Collision resistance","Avalanche effect"],c:2,x:"La résistance aux collisions empêche de trouver deux entrées différentes donnant le même hash.",r:"La résistance à la préimage empêche de retrouver l'entrée à partir du hash."},
{d:1,e:"hard",s:"Digital signatures provide which two main security services?",o:["Confidentiality and availability","Integrity and non-repudiation","Availability and authentication","Confidentiality only"],c:1,x:"Les signatures numériques fournissent l'intégrité et la non-répudiation.",r:"Elles ne chiffrent pas les données."},
{d:1,e:"hard",s:"When a system is configured to deny all access if it cannot reach a decision about a request, this is known as:",o:["Fail open","Fail closed","Fail soft","Fail safe for availability"],c:1,x:"Fail closed signifie que le système refuse l'accès en cas d'incapacité à décider.",r:"Fail open autorise l'accès par défaut."},
{d:1,e:"hard",s:"Which principle is most directly supported by granting users only the permissions required for their current role?",o:["Defense in depth","Separation of duties","Least privilege","Need to know"],c:2,x:"Le principe du moindre privilège limite les permissions au strict nécessaire.",r:"Need to know est plus spécifique à l'accès à l'information sensible."},
{d:1,e:"hard",s:"A security camera that is clearly visible to visitors is primarily acting as which type of control?",o:["Preventive","Detective","Deterrent","Corrective"],c:2,x:"Une caméra visible a un effet dissuasif (deterrent).",r:"Elle peut aussi être détective, mais son placement visible vise surtout à dissuader."},
{d:1,e:"hard",s:"Which of the following is the best example of an administrative control?",o:["Intrusion prevention system","Security awareness training policy","Biometric door lock","Disk encryption"],c:1,x:"Une politique de formation est un contrôle administratif.",r:"Un IPS est un contrôle technique."},
{d:1,e:"hard",s:"Purchasing an insurance policy to cover potential losses from a cyber incident is an example of:",o:["Risk avoidance","Risk mitigation","Risk transference","Risk acceptance"],c:2,x:"L'assurance est une forme de transfert de risque.",r:"La mitigation réduit le risque par des contrôles techniques ou organisationnels."},
{d:1,e:"hard",s:"Which access control model relies on security labels and mandatory rules that users cannot alter?",o:["Discretionary Access Control (DAC)","Role-Based Access Control (RBAC)","Mandatory Access Control (MAC)","Attribute-Based Access Control (ABAC)"],c:2,x:"Le MAC utilise des labels et des règles obligatoires non modifiables par les utilisateurs.",r:"Le DAC laisse le propriétaire de l'objet décider des droits."},
{d:1,e:"hard",s:"What is the primary objective of applying the principle of least privilege to service accounts?",o:["Make system administration more convenient","Reduce the potential impact if the account is compromised","Eliminate the need for monitoring service accounts","Allow the account to perform any action on the system"],c:1,x:"Limiter les droits des comptes de service réduit l'impact d'une éventuelle compromission.",r:"Ce n'est pas pour faciliter l'administration."},
{d:1,e:"hard",s:"A control that brings a system back to a secure state after an incident has occurred is classified as:",o:["Preventive","Detective","Corrective","Deterrent"],c:2,x:"Les contrôles correctifs rétablissent un état sécurisé après un incident.",r:"Les contrôles préventifs agissent avant l'incident."},
{d:1,e:"hard",s:"Which concept requires that critical tasks are divided so that no single individual has complete control?",o:["Least privilege","Need to know","Separation of duties","Defense in depth"],c:2,x:"La séparation des tâches divise les responsabilités pour éviter qu'une seule personne contrôle un processus critique.",r:"Le moindre privilège limite les droits mais ne divise pas forcément les rôles."},
{d:1,e:"hard",s:"In cryptography, the property that prevents a sender from denying that they sent a particular message is called:",o:["Confidentiality","Integrity","Non-repudiation","Availability"],c:2,x:"La non-répudiation empêche un acteur de nier avoir réalisé une action (envoyer un message, signer un document, etc.).",r:"L'intégrité garantit que le message n'a pas été modifié."},
{d:1,e:"hard",s:"Implementing a third-party MFA solution because a legacy application cannot support MFA natively is an example of a:",o:["Preventive control","Detective control","Compensating control","Deterrent control"],c:2,x:"Un contrôle compensatoire est mis en place lorsque le contrôle principal ne peut pas être appliqué directement.",r:"Ce n'est pas simplement un contrôle préventif."},
{d:1,e:"hard",s:"What does the principle of least privilege most directly aim to reduce?",o:["The need for strong authentication","The potential damage from a compromised account or process","The importance of data encryption","The requirement for security monitoring"],c:1,x:"Le moindre privilège réduit l'impact potentiel d'une compromission en limitant les droits.",r:"Il ne réduit pas le besoin d'authentification."},
{d:1,e:"hard",s:"Which of the following best describes defense in depth?",o:["Relying on a single strong security control","Using multiple complementary layers of security controls","Removing all controls except encryption","Trusting the internal network once a user is authenticated"],c:1,x:"La défense en profondeur consiste à superposer plusieurs couches de contrôles de nature différente.",r:"Une seule couche de protection est insuffisante."},
{d:1,e:"hard",s:"A company grants access to sensitive documents only to employees who have a legitimate business reason to view them. This is an example of:",o:["Least privilege","Separation of duties","Need to know","Defense in depth"],c:2,x:"Need to know limite l'accès à l'information en fonction du besoin professionnel réel.",r:"Le moindre privilège est plus large et s'applique aussi aux actions système."},
{d:1,e:"hard",s:"Which type of control is a locked server room door primarily considered?",o:["Technical","Administrative","Physical","Compensating"],c:2,x:"Une porte verrouillée est un contrôle physique.",r:"Une politique écrite serait un contrôle administratif."},
{d:1,e:"hard",s:"When the cost of implementing a control is higher than the expected loss from the risk, the organisation may choose:",o:["Risk avoidance","Risk mitigation","Risk transference","Informed risk acceptance"],c:3,x:"Si le coût du contrôle dépasse le bénéfice attendu, l'organisation peut accepter le risque de manière informée.",r:"Ce n'est pas de l'évitement du risque."},

{d:1,e:"really-hard",s:"In a Zero Trust security model, which traditional assumption is explicitly rejected?",o:["The need for strong multi-factor authentication","Trust based on network location (inside vs outside the perimeter)","The value of encrypting data at rest and in transit","The importance of continuous security monitoring"],c:1,x:"Zero Trust rejette la confiance implicite basée sur la localisation réseau (intérieur vs extérieur).",r:"L'authentification forte reste un élément central de Zero Trust."},
{d:1,e:"really-hard",s:"Which statement best describes the modern application of least privilege in cloud environments?",o:["Users and services should have permanent broad privileges for operational efficiency","Privileges should be granted just-in-time and just-enough, then automatically revoked","All users should receive administrator rights on their workstations by default","Service accounts should always be granted domain-level privileges"],c:1,x:"Dans les environnements cloud modernes, le moindre privilège s'applique de façon dynamique (just-in-time / just-enough).",r:"Les privilèges permanents élevés sont exactement ce qu'il faut éviter."},
{d:1,e:"really-hard",s:"A system is intentionally designed to deny all access when its policy decision point is unavailable. This design choice prioritises which security objectives?",o:["Availability over confidentiality and integrity","Confidentiality and integrity over availability","Performance over security","User convenience over risk reduction"],c:1,x:"Fail closed privilégie la confidentialité et l'intégrité au détriment de la disponibilité.",r:"Fail open aurait privilégié la disponibilité."},
{d:1,e:"really-hard",s:"Which metric is most useful for evaluating the real-world effectiveness of a security awareness programme?",o:["Number of training modules completed by employees","Number of security posters displayed in offices","Reduction in successful phishing simulations and incidents caused by human error","Total hours spent watching security training videos"],c:2,x:"La réduction des clics sur les simulations de phishing et des incidents liés à l'erreur humaine est le meilleur indicateur d'efficacité réelle.",r:"Le simple taux de complétion des modules ne mesure pas le changement de comportement."},
{d:1,e:"really-hard",s:"Why is encrypting data at rest by itself insufficient for a complete Zero Trust data protection strategy?",o:["Encryption automatically provides strong authentication of users","Access to the decryption keys and the context of each access request must still be continuously verified","Encryption removes the need for any form of access control","Encryption at rest is the only control required in a Zero Trust model"],c:1,x:"Même lorsque les données sont chiffrées, l'accès aux clés de déchiffrement et le contexte de chaque requête doivent être vérifiés en continu.",r:"Le chiffrement seul ne constitue pas une stratégie Zero Trust complète."},
{d:1,e:"really-hard",s:"Which statement about risk appetite is most accurate?",o:["Risk appetite is decided only after all security controls have been implemented","Risk appetite defines the amount of residual risk an organisation is willing to accept and therefore influences control selection","Risk appetite only applies to financial risks and not to cyber risks","Risk appetite is always identical to risk tolerance"],c:1,x:"L'appétit pour le risque définit le niveau de risque résiduel acceptable et guide le choix et la force des contrôles.",r:"Il n'est pas défini après la mise en place des contrôles."},
{d:1,e:"really-hard",s:"In a mature security programme, which approach is preferred when granting elevated privileges?",o:["Permanent standing administrator rights for convenience","Shared privileged accounts to reduce the total number of accounts","Just-in-time and just-enough access with automatic time-based revocation","No elevated privileges granted to anyone under any circumstances"],c:2,x:"L'accès juste-à-temps et juste-suffisant avec révocation automatique est l'approche préférée.",r:"Les privilèges permanents élevés augmentent considérablement le risque."},
{d:1,e:"really-hard",s:"Which of the following best illustrates the principle of defense in depth?",o:["Relying solely on a next-generation firewall at the perimeter","Combining network segmentation, endpoint detection, multi-factor authentication and continuous monitoring","Removing all security controls except encryption to simplify management","Trusting any user who has successfully authenticated to the VPN"],c:1,x:"La défense en profondeur combine plusieurs types de contrôles (préventifs, détectifs, etc.) sur les mêmes actifs.",r:"Une seule couche de protection est insuffisante."},
{d:1,e:"really-hard",s:"A control that is implemented because a primary preferred control cannot be used is best described as a:",o:["Preventive control","Detective control","Compensating control","Deterrent control"],c:2,x:"Un contrôle compensatoire est mis en place lorsque le contrôle principal ne peut pas être appliqué.",r:"Ce n'est pas simplement un contrôle préventif standard."},
{d:1,e:"really-hard",s:"Which statement best describes the correct relationship between policies, standards and procedures?",o:["The three terms are interchangeable and mean the same thing","Procedures are higher-level than policies","Policies set high-level direction, standards define mandatory requirements, and procedures provide detailed step-by-step instructions","Standards are always optional while policies are mandatory"],c:2,x:"Les politiques définissent la direction, les standards fixent les exigences obligatoires, les procédures décrivent les étapes concrètes.",r:"Ces trois termes ont des rôles distincts et ne sont pas interchangeables."},

{d:1,e:"hard",s:"Which of the following is an example of 'something you have' in multi-factor authentication?",o:["Password or PIN","Fingerprint or facial recognition","Hardware token or smart card","Geographic location"],c:2,x:"Un token matériel ou une smart card est un facteur 'something you have'.",r:"Un mot de passe est 'something you know'."},
{d:1,e:"hard",s:"What is the main security benefit of using mutual TLS between microservices?",o:["It only encrypts traffic in one direction","It provides cryptographic mutual authentication of both parties","It removes the need for any authorization logic","It automatically improves application performance"],c:1,x:"mTLS authentifie mutuellement les deux services de façon cryptographique.",r:"Il ne se contente pas de chiffrer dans un seul sens."},
{d:1,e:"hard",s:"A company implements both a web application firewall and regular source code reviews for the same application. This is an example of:",o:["Single point of failure","Defense in depth","Risk avoidance","Least privilege"],c:1,x:"Combiner un contrôle technique (WAF) et un contrôle processus (revue de code) illustre la défense en profondeur.",r:"Ce n'est pas un single point of failure."},
{d:1,e:"really-hard",s:"In the context of Zero Trust, what is continuously verified rather than assumed after the initial authentication?",o:["Only the strength of the user’s password","Only the source IP address of the connection","User identity, device posture and the context of each individual request","Only the time of day the request is made"],c:2,x:"Zero Trust vérifie en continu l'identité, la posture de l'appareil et le contexte de chaque requête.",r:"Une vérification uniquement au moment du login n'est pas du Zero Trust."},
{d:1,e:"hard",s:"Which of the following best demonstrates separation of duties in a software development environment?",o:["Developers can write code and deploy it directly to production","The same person writes, tests and approves production changes","Different people are responsible for development, testing and deployment to production","All developers are given full administrator rights on production systems"],c:2,x:"Séparer le développement, les tests et le déploiement en production applique la séparation des tâches.",r:"Permettre à la même personne de tout faire viole ce principe."},
{d:1,e:"really-hard",s:"Which of the following is the best example of a compensating control when multi-factor authentication cannot be enabled on a critical legacy system?",o:["Simply accepting the risk without any additional measures","Removing the system from the network without business justification","Enhanced monitoring, stricter network segmentation and more frequent access reviews for that system","Disabling all logging on the system to reduce noise"],c:2,x:"Des contrôles compensatoires (surveillance renforcée, segmentation, revues d'accès) atténuent le risque lorsque le contrôle principal est impossible.",r:"Accepter purement le risque n'est pas un contrôle compensatoire."},
{d:1,e:"hard",s:"What is the primary goal of non-repudiation in security?",o:["To encrypt sensitive data","To prevent a party from denying that they performed a specific action","To guarantee system availability","To hide the identity of the sender"],c:1,x:"La non-répudiation empêche un acteur de nier avoir réalisé une action précise.",r:"Elle ne sert pas à chiffrer les données."},
{d:1,e:"really-hard",s:"A security architect decides that administrative access to production systems must only be possible from hardened privileged access workstations. This decision primarily supports which principles?",o:["Maximum convenience for system administrators","Least privilege, reduced attack surface and separation of high-risk activities","Complete elimination of the need for monitoring administrative actions","Risk transference to the workstation manufacturer"],c:1,x:"Les PAW réduisent la surface d'attaque et séparent les activités à haut risque, en ligne avec le moindre privilège.",r:"Ce n'est pas pour maximiser le confort des administrateurs."},
{d:1,e:"hard",s:"Which of the following is considered a technical control?",o:["Security awareness training","Background check policy","Network firewall rules","Clean desk policy"],c:2,x:"Les règles de firewall sont un contrôle technique.",r:"La formation et les politiques sont des contrôles administratifs."},
{d:1,e:"really-hard",s:"Which statement best describes the purpose of a security baseline?",o:["It lists every possible vulnerability that could exist","It defines a minimum secure configuration that systems are expected to meet","It replaces the need for continuous monitoring","It is used only for compliance reporting and has no operational value"],c:1,x:"Une baseline de sécurité définit une configuration minimale sécurisée que les systèmes doivent respecter.",r:"Elle ne liste pas toutes les vulnérabilités possibles."},


// ===== DOMAIN 2 – 40 NEW QUESTIONS (Hard + Really Hard only) =====

{d:2,e:"hard",s:"An attacker requests TGS tickets for service accounts and cracks them offline. This technique is known as:",o:["AS-REP roasting","Pass-the-hash","Kerberoasting","Golden ticket"],c:2,x:"Kerberoasting consiste à demander des TGS pour des comptes de service puis à les cracker hors ligne.",r:"AS-REP roasting cible les comptes sans pré-authentification."},
{d:2,e:"hard",s:"Which attack targets accounts that have the 'Do not require Kerberos preauthentication' flag set?",o:["Kerberoasting","Silver ticket","AS-REP roasting","DCSync"],c:2,x:"AS-REP roasting cible les comptes configurés sans pré-authentification Kerberos.",r:"Kerberoasting travaille sur les TGS."},
{d:2,e:"hard",s:"An attacker forges a TGT using the KRBTGT account hash. This is called a:",o:["Silver ticket","Golden ticket","Diamond ticket","Sapphire ticket"],c:1,x:"Le Golden Ticket est un TGT forgé avec le hash du compte KRBTGT.",r:"Le Silver Ticket est un TGS forgé avec le hash d'un compte de service."},
{d:2,e:"hard",s:"Which technique allows an attacker to retrieve password hashes by abusing directory replication privileges?",o:["DCShadow","Golden ticket","DCSync","Kerberoasting"],c:2,x:"DCSync abuse des droits de réplication pour récupérer les hashes comme le ferait un contrôleur de domaine.",r:"DCShadow injecte des objets via un faux DC."},
{d:2,e:"hard",s:"An attacker registers a rogue domain controller to inject malicious objects into Active Directory. This is known as:",o:["DCSync","Skeleton Key","DCShadow","Pass-the-ticket"],c:2,x:"DCShadow permet d'enregistrer un faux contrôleur de domaine et d'injecter des modifications.",r:"DCSync lit les données, DCShadow les écrit."},
{d:2,e:"hard",s:"Using a legitimate Windows binary to download and execute a malicious payload is an example of:",o:["Traditional dropper","Living-off-the-land binary (LOLBin) technique","Bootkit","Rootkit only"],c:1,x:"L'utilisation de binaires légitimes du système pour exécuter du code malveillant est une technique LotL.",r:"Un dropper traditionnel apporte son propre exécutable."},
{d:2,e:"hard",s:"Which vulnerability allows an attacker to force the server to make requests to arbitrary internal or external resources?",o:["Cross-Site Request Forgery (CSRF)","Server-Side Request Forgery (SSRF)","Cross-Site Scripting (XSS)","SQL injection"],c:1,x:"SSRF force le serveur à émettre des requêtes vers des ressources choisies par l'attaquant.",r:"CSRF force le navigateur de la victime."},
{d:2,e:"hard",s:"An attacker injects a malicious script that is permanently stored on the server and executed for other users. This is:",o:["Reflected XSS","DOM-based XSS","Stored XSS","CSRF"],c:2,x:"Le XSS stocké (persistent) reste sur le serveur et s'exécute pour les autres utilisateurs.",r:"Le XSS réfléchi ne s'exécute que dans le contexte de la requête immédiate."},
{d:2,e:"hard",s:"Which attack forces an authenticated user’s browser to send unwanted requests to a web application?",o:["SQL injection","Cross-Site Scripting (XSS)","Cross-Site Request Forgery (CSRF)","Server-Side Request Forgery (SSRF)"],c:2,x:"CSRF force le navigateur de la victime authentifiée à envoyer des requêtes non voulues.",r:"XSS injecte du script, CSRF force une action."},
{d:2,e:"hard",s:"An attacker manipulates file path inputs to access files outside the intended directory. This is called:",o:["SQL injection","Command injection","Directory / path traversal","XSS"],c:2,x:"Le path traversal manipule les chemins pour accéder à des fichiers non autorisés.",r:"Ce n'est pas une injection SQL."},
{d:2,e:"hard",s:"Which technique involves an attacker becoming the root bridge in a Spanning Tree topology to intercept traffic?",o:["VLAN hopping","MAC flooding","STP root bridge attack","ARP spoofing"],c:2,x:"En devenant root bridge, l'attaquant peut forcer le trafic à passer par lui.",r:"Le MAC flooding sature la table CAM du switch."},
{d:2,e:"hard",s:"An attacker floods a switch with fake MAC addresses until it starts forwarding traffic like a hub. This is:",o:["ARP spoofing","VLAN hopping","MAC flooding / CAM table overflow","STP attack"],c:2,x:"Le MAC flooding sature la table CAM du switch, le faisant se comporter comme un hub.",r:"L'ARP spoofing empoisonne les caches ARP."},
{d:2,e:"hard",s:"Which attack uses double tagging of 802.1Q frames to reach a different VLAN?",o:["MAC flooding","ARP spoofing","VLAN hopping (double tagging)","STP manipulation"],c:2,x:"Le double tagging permet dans certaines configurations de sauter d'un VLAN à un autre.",r:"Le MAC flooding sature la table d'adresses MAC."},
{d:2,e:"hard",s:"An attacker sets up a rogue DHCP server to provide malicious network configuration to clients. This is known as:",o:["DHCP starvation","ARP spoofing","DHCP spoofing / rogue DHCP","DNS cache poisoning"],c:2,x:"Un serveur DHCP pirate peut distribuer une fausse passerelle ou de faux DNS.",r:"La famine DHCP épuise le pool d'adresses."},
{d:2,e:"hard",s:"Which technique exhausts the available IP addresses on a DHCP server so legitimate clients cannot obtain one?",o:["DHCP spoofing","ARP spoofing","DHCP starvation","DNS poisoning"],c:2,x:"La famine DHCP consiste à demander massivement des adresses pour épuiser le pool.",r:"Le DHCP spoofing fournit de fausses configurations."},
{d:2,e:"hard",s:"An attacker poisons the local ARP cache so that their MAC address is associated with the IP of the default gateway. This is:",o:["DNS spoofing","MAC flooding","ARP spoofing / ARP poisoning","VLAN hopping"],c:2,x:"L'ARP spoofing permet de se positionner en homme du milieu sur le réseau local.",r:"Le DNS spoofing travaille sur les résolutions de noms."},
{d:2,e:"hard",s:"Which attack uses ICMP packets to carry covert command-and-control or data exfiltration traffic?",o:["DNS tunneling","HTTP tunneling","ICMP tunneling","SMTP tunneling"],c:2,x:"Le tunneling ICMP encapsule des données dans des paquets ICMP.",r:"Le tunneling DNS utilise le protocole DNS."},
{d:2,e:"hard",s:"An attacker stages large amounts of data on an internal system before sending it out slowly. This activity is part of:",o:["Initial access","Privilege escalation","Data exfiltration / staging","Persistence only"],c:2,x:"Le staging suivi d'une exfiltration discrète est une phase classique des attaques avancées.",r:"Ce n'est pas de la persistance."},
{d:2,e:"hard",s:"Which technique allows an attacker to use a compromised host as a stepping stone to reach other internal systems?",o:["Credential dumping only","Pivoting","Persistence only","Defense evasion only"],c:1,x:"Le pivoting consiste à utiliser une machine compromise comme point de rebond vers d'autres systèmes.",r:"Ce n'est pas uniquement du dumping d'identifiants."},
{d:2,e:"hard",s:"An attacker uses Unicode characters that look identical to Latin letters in a domain name. This is called a:",o:["Typosquatting attack","Homograph / IDN homograph attack","Watering hole attack","Spear phishing"],c:1,x:"Les attaques homographes exploitent des caractères Unicode visuellement similaires.",r:"Le typosquatting utilise des fautes de frappe classiques."},

{d:2,e:"really-hard",s:"An attacker has WriteOwner rights on a Group Policy Object linked to the Domain Controllers OU. What is the MOST dangerous next step?",o:["Rename the GPO","Unlink the GPO","Deploy a malicious scheduled task or script that runs as SYSTEM on all Domain Controllers","Delete the GPO"],c:2,x:"Avec WriteOwner sur un GPO lié aux Domain Controllers, l'attaquant peut y injecter un script malveillant qui s'exécute en SYSTEM.",r:"Renommer ou supprimer le GPO a un impact beaucoup plus limité."},
{d:2,e:"really-hard",s:"An attacker forces a Domain Controller to authenticate to a system under their control (using PrinterBug or PetitPotam) and then relays that authentication to AD CS HTTP enrollment. This attack chain is known as:",o:["Classic Kerberoasting","Simple pass-the-hash","Authentication coercion + NTLM relay leading to ESC8","AS-REP roasting"],c:2,x:"Cette chaîne (coercion d'authentification + relais NTLM vers AD CS) est une attaque de type ESC8.",r:"Ce n'est pas du Kerberoasting."},
{d:2,e:"really-hard",s:"An attacker compromises a computer account and then configures the msDS-AllowedToActOnBehalfOfOtherIdentity attribute on a high-value server. They are preparing which attack?",o:["Classic unconstrained delegation","Kerberoasting","Resource-Based Constrained Delegation (RBCD)","DCSync"],c:2,x:"Configurer msDS-AllowedToActOnBehalfOfOtherIdentity est l'étape clé d'une attaque RBCD.",r:"Ce n'est pas de la délégation non contrainte classique."},
{d:2,e:"really-hard",s:"Which technique allows an attacker to forge Kerberos service tickets without needing the KRBTGT hash?",o:["Golden Ticket","Silver Ticket","Diamond Ticket","Sapphire Ticket"],c:1,x:"Un Silver Ticket est un TGS forgé avec le hash du compte de service, sans avoir besoin du hash KRBTGT.",r:"Le Golden Ticket nécessite le hash KRBTGT."},
{d:2,e:"really-hard",s:"An attacker has obtained the KRBTGT hash. What is the MOST impactful long-term action they can take?",o:["Only create one Silver Ticket","Only perform Kerberoasting","Create Golden Tickets that provide long-term domain persistence","Only perform AS-REP roasting"],c:2,x:"Le hash KRBTGT permet de créer des Golden Tickets offrant une persistance très durable au niveau du domaine.",r:"Les Silver Tickets ne nécessitent pas le hash KRBTGT."},
{d:2,e:"really-hard",s:"Which attack path is typically characterised by a chain of abusable ACLs, group memberships and delegations that eventually lead to Domain Admin?",o:["Single vulnerability that always gives instant Domain Admin","Active Directory attack path (BloodHound-style path)","Only external phishing","Only password spraying"],c:1,x:"Les chemins d'attaque AD modernes sont généralement des chaînes de permissions et de configurations abusables.",r:"Il est rare qu'une seule vulnérabilité donne directement Domain Admin."},
{d:2,e:"really-hard",s:"An attacker uses a stolen certificate to request a TGT via PKINIT and then impersonates a high-privilege user. This is an example of:",o:["Classic password-based Kerberoasting","AS-REP roasting","Certificate-based Kerberos authentication abuse","NTLM relay only"],c:2,x:"Avec un certificat approprié, un attaquant peut obtenir un TGT via PKINIT.",r:"Ce n'est pas du Kerberoasting classique basé sur les mots de passe."},
{d:2,e:"really-hard",s:"Which combination of defenses MOST effectively reduces the risk of classic NTLM relay attacks?",o:["Only account lockout policies","Only password complexity requirements","SMB signing required + LDAP signing/channel binding + Extended Protection for Authentication","Disabling all computer accounts"],c:2,x:"La signature SMB, la protection LDAP et EPA sont des mitigations clés contre le relais NTLM.",r:"La complexité des mots de passe ne protège pas contre le relais."},
{d:2,e:"really-hard",s:"An attacker injects the SID of a privileged group from another domain into a token using SID History. This technique is most dangerous when:",o:["SID filtering is enabled and strictly enforced","All trusts are one-way only","SID filtering is disabled on the trust","Kerberos is completely disabled"],c:2,x:"Sans filtrage SID, l'injection de SID History peut apporter des privilèges d'un domaine à un autre.",r:"Le filtrage SID est conçu précisément pour bloquer cette technique."},
{d:2,e:"really-hard",s:"Which defense MOST effectively reduces the success rate of Kerberoasting attacks against service accounts?",o:["Disabling Kerberos entirely","Using only NTLM authentication","Group Managed Service Accounts (gMSA) or extremely long unique passwords + monitoring of unusual TGS requests","Removing all SPNs from the domain"],c:2,x:"Les gMSA et les mots de passe extrêmement robustes, combinés à de la détection, réduisent fortement le risque Kerberoasting.",r:"Désactiver Kerberos n'est généralement pas réaliste."},

{d:2,e:"hard",s:"Which technique involves modifying the legitimate code of a running process in memory?",o:["Simple file replacement on disk","Process injection / process hollowing","Only registry modification","Only scheduled task creation"],c:1,x:"L'injection ou le process hollowing se fait en mémoire sur un processus légitime.",r:"Ce n'est pas une simple modification de fichier sur le disque."},
{d:2,e:"hard",s:"An attacker uses a compromised internal email account to send phishing messages to other employees. This is an example of:",o:["External spear phishing only","Whaling only","Business Email Compromise / lateral phishing","Vishing"],c:2,x:"L'utilisation d'un compte email interne compromis pour phisher d'autres employés est du BEC / phishing latéral.",r:"Ce n'est plus du phishing purement externe."},
{d:2,e:"hard",s:"Which attack uses voice calls to socially engineer victims into revealing information or performing actions?",o:["Smishing","Phishing","Vishing","Whaling"],c:2,x:"Le vishing est du phishing réalisé par appel téléphonique.",r:"Le smishing utilise les SMS."},
{d:2,e:"hard",s:"Malicious SMS messages designed to trick users into clicking links or revealing information are called:",o:["Vishing","Spear phishing","Smishing","Whaling"],c:2,x:"Le smishing est du phishing par SMS.",r:"Le vishing passe par la voix."},
{d:2,e:"hard",s:"Registering domain names that are slight misspellings of legitimate brand names is known as:",o:["Homograph attack","Watering hole","Typosquatting","Spear phishing"],c:2,x:"Le typosquatting enregistre des noms de domaine proches pour tromper les utilisateurs.",r:"Les attaques homographes utilisent des caractères Unicode ressemblants."},
{d:2,e:"really-hard",s:"An attacker has WriteDACL rights on an Organisational Unit containing privileged accounts. What is the MOST likely high-impact next step?",o:["Immediately attempt to crack all passwords in the OU","Only perform Kerberoasting on the accounts","Modify ACLs to grant themselves additional rights or create a shadow principal","Only delete the accounts"],c:2,x:"Avec WriteDACL, l'attaquant peut modifier les permissions pour s'accorder d'autres droits et progresser vers des privilèges élevés.",r:"Cracker les mots de passe n'est pas forcément l'étape la plus efficace."},
{d:2,e:"really-hard",s:"Which technique combines authentication coercion with NTLM relay to Active Directory Certificate Services to obtain a privileged certificate?",o:["Classic Golden Ticket attack","Kerberoasting","ESC8-style attack","AS-REP roasting"],c:2,x:"ESC8 combine la coercion d'authentification et le relais NTLM vers l'interface d'inscription web d'AD CS.",r:"Ce n'est pas un Golden Ticket."},
{d:2,e:"hard",s:"An attacker forces a machine to authenticate to a system they control and then relays that authentication. This is commonly part of:",o:["Simple password spraying","Kerberoasting only","Authentication coercion + NTLM relay attacks","AS-REP roasting only"],c:2,x:"La coercion d'authentification suivie d'un relais NTLM est une technique avancée très utilisée.",r:"Ce n'est pas du spraying de mots de passe."},
{d:2,e:"really-hard",s:"Which attack allows an adversary to forge inter-realm tickets and move from a compromised domain into a trusting domain?",o:["Simple Silver Ticket inside one domain","Classic Kerberoasting only","Trust ticket attacks / inter-realm ticket abuse","AS-REP roasting only"],c:2,x:"Les tickets inter-royaumes forgés ou abusés permettent de traverser les relations d'approbation.",r:"Ce n'est pas un simple Silver Ticket local."},
{d:2,e:"hard",s:"Which malware technique is specifically designed to remain hidden and maintain long-term privileged access?",o:["Ransomware only","Adware only","Rootkit or advanced persistent implant","Scareware only"],c:2,x:"Les rootkits et implants APT sont conçus pour la discrétion et la persistance longue durée.",r:"Le ransomware a un objectif de chiffrement et de rançon."},

// ===== DOMAIN 2 – 40 NEW QUESTIONS (Hard + Really Hard only) =====

{d:2,e:"hard",s:"An attacker captures NTLM authentication traffic and reuses it to access another system. This is a form of:",o:["Kerberoasting","AS-REP roasting","Pass-the-hash / NTLM relay","Golden ticket"],c:2,x:"La réutilisation d'un échange NTLM capturé est typique du pass-the-hash ou du relais NTLM.",r:"Kerberoasting travaille sur les tickets TGS."},
{d:2,e:"hard",s:"Which technique involves requesting a service ticket and then attempting to crack it offline?",o:["AS-REP roasting","Pass-the-ticket","Kerberoasting","DCSync"],c:2,x:"Kerberoasting = demander un TGS pour un compte de service puis le cracker hors ligne.",r:"AS-REP roasting cible les comptes sans pré-authentification."},
{d:2,e:"hard",s:"An attacker forges a service ticket using the hash of a service account. This is known as a:",o:["Golden ticket","Silver ticket","Diamond ticket","Sapphire ticket"],c:1,x:"Un Silver Ticket est un TGS forgé avec le hash du compte de service.",r:"Le Golden Ticket est un TGT forgé avec le hash KRBTGT."},
{d:2,e:"hard",s:"Which attack abuses directory replication rights to extract password hashes from a domain controller?",o:["DCShadow","Golden ticket","DCSync","Kerberoasting"],c:2,x:"DCSync simule un contrôleur de domaine pour demander les hashes via la réplication.",r:"DCShadow injecte des objets dans AD."},
{d:2,e:"hard",s:"An attacker uses a legitimate system tool such as certutil or bitsadmin to download a payload. This is an example of:",o:["Traditional malware dropper","Living-off-the-land technique","Bootkit","Firmware rootkit"],c:1,x:"L'utilisation d'outils légitimes du système pour des actions malveillantes est une technique living-off-the-land.",r:"Un dropper classique apporte son propre binaire."},
{d:2,e:"hard",s:"Which vulnerability allows an attacker to induce the server to make HTTP requests to an arbitrary domain?",o:["Cross-Site Request Forgery","Server-Side Request Forgery","Cross-Site Scripting","SQL injection"],c:1,x:"SSRF force le serveur à effectuer des requêtes vers une ressource choisie par l'attaquant.",r:"CSRF force le navigateur de la victime."},
{d:2,e:"hard",s:"An attacker injects malicious JavaScript that is saved in the application database and executed when other users view the page. This is:",o:["Reflected XSS","DOM-based XSS","Stored (persistent) XSS","CSRF"],c:2,x:"Le XSS stocké reste dans la base de données et s'exécute pour tous les utilisateurs qui consultent la page.",r:"Le XSS réfléchi ne s'exécute que dans la requête immédiate."},
{d:2,e:"hard",s:"Which attack tricks a user’s browser into sending an authenticated request to a web application without the user’s consent?",o:["SQL injection","Cross-Site Scripting","Cross-Site Request Forgery","Server-Side Request Forgery"],c:2,x:"CSRF exploite la session authentifiée de la victime pour envoyer des requêtes non désirées.",r:"XSS injecte du code, CSRF force une action."},
{d:2,e:"hard",s:"An attacker uses ../ sequences in a file parameter to access files outside the web root. This is called:",o:["SQL injection","Command injection","Path traversal / directory traversal","XSS"],c:2,x:"Le path traversal manipule le chemin pour sortir du répertoire prévu.",r:"Ce n'est pas une injection SQL."},
{d:2,e:"hard",s:"Which network attack causes a switch to forward traffic to all ports by overflowing its MAC address table?",o:["ARP spoofing","VLAN hopping","MAC flooding","STP root attack"],c:2,x:"Le MAC flooding sature la table CAM du switch, le faisant se comporter comme un hub.",r:"L'ARP spoofing empoisonne les caches ARP des hôtes."},
{d:2,e:"hard",s:"An attacker sends frames with two 802.1Q tags to reach a VLAN they should not have access to. This technique is known as:",o:["MAC flooding","ARP spoofing","VLAN hopping (double tagging)","STP manipulation"],c:2,x:"Le double tagging permet dans certaines configurations de traverser les VLAN.",r:"Le MAC flooding sature la table d'adresses MAC."},
{d:2,e:"hard",s:"Which attack involves installing a rogue DHCP server to provide clients with malicious network configuration?",o:["DHCP starvation","ARP spoofing","DHCP spoofing","DNS cache poisoning"],c:2,x:"Un serveur DHCP pirate peut distribuer une fausse passerelle ou de faux serveurs DNS.",r:"La famine DHCP épuise le pool d'adresses."},
{d:2,e:"hard",s:"An attacker exhausts the DHCP IP pool so that legitimate clients cannot obtain an address. This is called:",o:["DHCP spoofing","ARP spoofing","DHCP starvation","DNS poisoning"],c:2,x:"La famine DHCP consiste à demander un grand nombre d'adresses pour saturer le serveur.",r:"Le DHCP spoofing fournit de fausses configurations."},
{d:2,e:"hard",s:"Which technique associates the attacker’s MAC address with the IP address of the default gateway in victims’ ARP caches?",o:["DNS spoofing","MAC flooding","ARP spoofing / ARP poisoning","VLAN hopping"],c:2,x:"L'ARP spoofing permet de se placer en homme du milieu sur le réseau local.",r:"Le DNS spoofing cible les résolutions de noms."},
{d:2,e:"hard",s:"An attacker encapsulates command-and-control traffic inside ICMP echo packets. This is an example of:",o:["DNS tunneling","HTTP tunneling","ICMP tunneling","SMTP tunneling"],c:2,x:"Le tunneling ICMP cache des données dans des paquets ICMP.",r:"Le tunneling DNS utilise les requêtes DNS."},
{d:2,e:"hard",s:"Which phase of an attack involves collecting and preparing data on a compromised host before sending it outside the network?",o:["Initial access","Privilege escalation","Data staging / exfiltration preparation","Persistence"],c:2,x:"Le staging consiste à rassembler et préparer les données avant l'exfiltration.",r:"Ce n'est pas de la persistance."},
{d:2,e:"hard",s:"An attacker uses a compromised workstation to reach other internal systems that are not directly accessible. This is known as:",o:["Credential dumping","Pivoting / lateral movement via jump host","Persistence","Defense evasion only"],c:1,x:"Le pivoting utilise une machine compromise comme point de rebond vers d'autres systèmes internes.",r:"Ce n'est pas uniquement du dumping d'identifiants."},
{d:2,e:"hard",s:"Which attack registers domain names that closely resemble legitimate brands using look-alike Unicode characters?",o:["Typosquatting","Homograph attack","Watering hole","Spear phishing"],c:1,x:"Les attaques homographes exploitent des caractères Unicode qui ressemblent à des lettres latines.",r:"Le typosquatting utilise des fautes de frappe ordinaires."},
{d:2,e:"hard",s:"An attacker sends SMS messages containing malicious links to steal credentials. This is called:",o:["Vishing","Spear phishing","Smishing","Whaling"],c:2,x:"Le smishing est du phishing réalisé par SMS.",r:"Le vishing utilise la voix (appels téléphoniques)."},
{d:2,e:"hard",s:"Which social engineering technique uses phone calls to manipulate victims into revealing sensitive information?",o:["Smishing","Phishing","Vishing","Whaling"],c:2,x:"Le vishing est de l'ingénierie sociale par appel téléphonique.",r:"Le smishing passe par SMS."},

{d:2,e:"really-hard",s:"An attacker has WriteOwner permission on a GPO linked to the Domain Controllers OU. What is the most dangerous action they can take?",o:["Rename the GPO","Unlink the GPO from the OU","Deploy a malicious startup script or scheduled task that runs as SYSTEM on all Domain Controllers","Delete the GPO"],c:2,x:"Avec WriteOwner sur un GPO des Domain Controllers, l'attaquant peut déployer du code qui s'exécute en SYSTEM sur tous les DC.",r:"Renommer ou supprimer le GPO a un impact bien plus faible."},
{d:2,e:"really-hard",s:"An attacker coerces a Domain Controller to authenticate to a machine they control and then relays the authentication to Active Directory Certificate Services. This attack chain is commonly referred to as:",o:["Classic Kerberoasting","Simple pass-the-hash","Authentication coercion + NTLM relay (ESC8)","AS-REP roasting"],c:2,x:"Cette combinaison (coercion + relais vers AD CS) est une attaque de type ESC8.",r:"Ce n'est pas du Kerberoasting."},
{d:2,e:"really-hard",s:"An attacker controls a computer account and sets the msDS-AllowedToActOnBehalfOfOtherIdentity attribute on a target server. They are preparing which attack?",o:["Unconstrained delegation abuse","Kerberoasting","Resource-Based Constrained Delegation (RBCD)","DCSync"],c:2,x:"La modification de msDS-AllowedToActOnBehalfOfOtherIdentity est l'étape centrale d'une attaque RBCD.",r:"Ce n'est pas de la délégation non contrainte classique."},
{d:2,e:"really-hard",s:"Which technique allows an attacker to create forged service tickets without possessing the KRBTGT hash?",o:["Golden Ticket","Silver Ticket","Diamond Ticket","Sapphire Ticket"],c:1,x:"Un Silver Ticket est forgé avec le hash du compte de service, sans avoir besoin du hash KRBTGT.",r:"Le Golden Ticket nécessite le hash KRBTGT."},
{d:2,e:"really-hard",s:"An attacker has obtained the KRBTGT account hash. What is the most powerful long-term action they can take?",o:["Create a single Silver Ticket","Perform Kerberoasting only","Create Golden Tickets for persistent domain-wide access","Perform AS-REP roasting only"],c:2,x:"Le hash KRBTGT permet de générer des Golden Tickets qui offrent une persistance durable au niveau du domaine.",r:"Les Silver Tickets ne nécessitent pas le hash KRBTGT."},
{d:2,e:"really-hard",s:"Which type of attack path is typically discovered using tools like BloodHound and consists of chained permissions and group memberships?",o:["A single critical vulnerability that immediately grants Domain Admin","Active Directory attack path","External phishing campaign only","Password spraying only"],c:1,x:"Les chemins d'attaque AD sont des chaînes de droits, groupes et configurations abusables menant à des privilèges élevés.",r:"Il est rare qu'une seule vulnérabilité donne directement Domain Admin."},
{d:2,e:"really-hard",s:"An attacker uses a stolen smart-card certificate or software certificate to request a TGT via PKINIT. This is an example of:",o:["Classic Kerberoasting","AS-REP roasting","Certificate-based Kerberos abuse","NTLM relay only"],c:2,x:"Avec un certificat valide, un attaquant peut obtenir un TGT via PKINIT et impersonner l'utilisateur.",r:"Ce n'est pas du Kerberoasting basé sur les mots de passe."},
{d:2,e:"really-hard",s:"Which combination of controls is most effective against classic NTLM relay attacks?",o:["Account lockout policies only","Password complexity requirements only","SMB signing + LDAP signing/channel binding + Extended Protection for Authentication","Disabling all computer accounts"],c:2,x:"La signature SMB, la protection LDAP et EPA sont les mitigations principales contre le relais NTLM.",r:"La complexité des mots de passe ne protège pas contre le relais."},
{d:2,e:"really-hard",s:"An attacker adds a privileged SID from another domain into a user’s SID History. This technique is most dangerous when:",o:["SID filtering is enabled on the trust","All trusts are strictly one-way","SID filtering is disabled on the trust relationship","Kerberos is disabled domain-wide"],c:2,x:"Lorsque le filtrage SID est désactivé, l'injection de SID History peut apporter des privilèges inter-domaines.",r:"Le filtrage SID est conçu pour empêcher cette technique."},
{d:2,e:"really-hard",s:"Which measure most effectively reduces the success of Kerberoasting against service accounts?",o:["Disabling Kerberos protocol entirely","Forcing all authentication to use NTLM","Using Group Managed Service Accounts (gMSA) or very long random passwords + detecting unusual TGS requests","Removing every SPN from the domain"],c:2,x:"Les gMSA et les mots de passe extrêmement longs, associés à de la détection, réduisent fortement le risque Kerberoasting.",r:"Désactiver Kerberos n'est généralement pas envisageable."},

{d:2,e:"hard",s:"Which technique modifies a running legitimate process in memory to hide malicious code?",o:["File replacement on disk","Process injection or process hollowing","Registry Run key modification only","Scheduled task creation only"],c:1,x:"L'injection de processus ou le process hollowing se déroule en mémoire sur un processus légitime.",r:"Ce n'est pas une simple modification de fichier."},
{d:2,e:"hard",s:"An attacker who has compromised an employee’s mailbox uses it to send further phishing emails to colleagues. This is an example of:",o:["External spear phishing","Whaling","Business Email Compromise / internal lateral phishing","Vishing"],c:2,x:"L'utilisation d'un compte email interne compromis pour phisher d'autres employés est du BEC / phishing latéral.",r:"Ce n'est plus une attaque purement externe."},
{d:2,e:"hard",s:"Which technique uses voice calls to socially engineer targets into divulging information or performing actions?",o:["Smishing","Phishing","Vishing","Whaling"],c:2,x:"Le vishing est de l'ingénierie sociale par téléphone.",r:"Le smishing utilise les SMS."},
{d:2,e:"hard",s:"Malicious messages sent via SMS that attempt to steal credentials or deliver malware are called:",o:["Vishing","Spear phishing","Smishing","Whaling"],c:2,x:"Le smishing est du phishing par SMS.",r:"Le vishing passe par des appels vocaux."},
{d:2,e:"hard",s:"Registering domain names that are common misspellings of popular brands is known as:",o:["Homograph attack","Watering hole attack","Typosquatting","Spear phishing"],c:2,x:"Le typosquatting exploite les fautes de frappe dans les noms de domaine.",r:"Les attaques homographes utilisent des caractères Unicode ressemblants."},
{d:2,e:"really-hard",s:"An attacker has WriteDACL rights on an OU that contains privileged accounts. What is the most impactful next step?",o:["Attempt to crack every password in the OU immediately","Perform only Kerberoasting on the accounts","Modify the ACLs to grant themselves additional rights or create a shadow principal","Delete all accounts in the OU"],c:2,x:"Avec WriteDACL l'attaquant peut modifier les permissions pour s'accorder plus de droits et progresser vers des privilèges élevés.",r:"Cracker les mots de passe n'est pas forcément l'action la plus efficace."},
{d:2,e:"really-hard",s:"Which attack combines authentication coercion with an NTLM relay to the Active Directory Certificate Services web enrollment endpoint?",o:["Classic Golden Ticket","Kerberoasting","ESC8-style attack","AS-REP roasting"],c:2,x:"ESC8 combine coercion d'authentification et relais NTLM vers l'interface d'inscription HTTP d'AD CS.",r:"Ce n'est pas un Golden Ticket."},
{d:2,e:"hard",s:"An attacker forces a machine to authenticate to a system under their control and then relays that authentication. This is typically part of:",o:["Password spraying only","Kerberoasting only","Authentication coercion + NTLM relay","AS-REP roasting only"],c:2,x:"La coercion d'authentification suivie d'un relais NTLM est une technique avancée très utilisée.",r:"Ce n'est pas du spraying de mots de passe."},
{d:2,e:"really-hard",s:"Which technique allows an attacker who has compromised one domain to move into a trusting domain by abusing inter-realm tickets?",o:["Simple Silver Ticket inside the compromised domain","Classic Kerberoasting only","Trust ticket / inter-realm ticket abuse","AS-REP roasting only"],c:2,x:"L'abus de tickets inter-royaumes permet de traverser les relations d'approbation entre domaines.",r:"Ce n'est pas un simple Silver Ticket local."},
{d:2,e:"hard",s:"Which type of malware is specifically designed to hide its presence and maintain long-term privileged access on a system?",o:["Ransomware","Adware","Rootkit or advanced persistent implant","Scareware"],c:2,x:"Les rootkits et implants APT sont conçus pour rester discrets et persister longtemps.",r:"Le ransomware a pour objectif principal le chiffrement et la rançon."},



// ====================== DOMAIN 3 ======================
{d:3,e:"medium",s:"Which network zone is typically used to host public-facing web servers?",o:["DMZ","Internal LAN","Management network","Guest network"],c:0,x:"La DMZ héberge les serveurs exposés à Internet.",r:"Le réseau interne n'est pas directement exposé."},
{d:3,e:"medium",s:"Which device is primarily used to control traffic between different networks based on rules?",o:["Switch","Hub","Firewall","Repeater"],c:2,x:"Le firewall contrôle le trafic entre réseaux selon des règles.",r:"Un switch travaille principalement au niveau 2."},
{d:3,e:"medium",s:"What is the main purpose of network segmentation?",o:["Make the network faster","Eliminate the need for firewalls","Limit the impact of a compromise and control traffic between zones","Allow all traffic by default"],c:2,x:"La segmentation limite l'impact d'une compromission et contrôle le trafic.",r:"Elle ne rend pas forcément le réseau plus rapide."},

{d:3,e:"hard",s:"Which cloud model gives the customer the MOST responsibility for security?",o:["IaaS","PaaS","SaaS","FaaS"],c:0,x:"En IaaS le client a le plus de responsabilités de sécurité.",r:"En SaaS le fournisseur en a le plus."},
{d:3,e:"hard",s:"Which architecture evaluates every access request regardless of network location?",o:["Traditional perimeter security","Flat network","Zero Trust","VPN-only access"],c:2,x:"Zero Trust évalue chaque requête indépendamment de la localisation réseau.",r:"Le modèle périmétrique fait confiance à l'intérieur."},
{d:3,e:"hard",s:"Placing administrative interfaces on a separate network with no direct internet access is an example of:",o:["In-band management","Out-of-band management","Management through the production network","Internet-exposed management"],c:1,x:"La gestion hors bande isole les interfaces d'administration.",r:"La gestion in-band utilise le réseau de production."},
{d:3,e:"hard",s:"Which technology provides strong isolation by giving each virtual machine its own kernel?",o:["Containers","Process isolation only","Type 1 hypervisor","Application sandboxing only"],c:2,x:"Les hyperviseurs de Type 1 offrent une isolation forte avec un noyau par VM.",r:"Les conteneurs partagent le noyau de l'hôte."},
{d:3,e:"hard",s:"Why should database servers generally have no direct route to the internet?",o:["To improve database performance","To simplify IP addressing","To reduce the attack surface and limit exfiltration paths","To make backups faster"],c:2,x:"Empêcher l'accès internet direct réduit la surface d'attaque et les possibilités d'exfiltration.",r:"Ce n'est pas pour la performance."},
{d:3,e:"hard",s:"Which approach is MOST aligned with Zero Trust for remote access to internal applications?",o:["Traditional VPN that places the user on the internal network","Direct exposure of applications to the internet","ZTNA that grants access only to specific applications after continuous verification","IP whitelisting of all remote users"],c:2,x:"ZTNA limite l'accès à l'application spécifique après vérification continue.",r:"Le VPN traditionnel donne souvent un accès réseau trop large."},

{d:3,e:"really-hard",s:"In a Zero Trust architecture, which statement about the network is MOST accurate?",o:["The network is considered hostile by default and every request is evaluated","Internal networks are fully trusted once authenticated","A VPN connection is sufficient to grant broad access","Micro-segmentation is unnecessary if identity is strong"],c:0,x:"En Zero Trust, le réseau est considéré comme hostile par défaut et chaque requête est évaluée.",r:"La confiance basée sur la localisation réseau est rejetée."},
{d:3,e:"really-hard",s:"Which statement about container security is MOST accurate?",o:["Each container runs a completely separate kernel","Containers provide the same isolation as full virtual machines","Containers share the host kernel, so a kernel vulnerability can affect all containers","Container escape is theoretically impossible"],c:2,x:"Les conteneurs partagent le noyau de l'hôte, ce qui crée une surface d'attaque différente des VMs.",r:"Les VMs ont un noyau séparé grâce à l'hyperviseur."},
{d:3,e:"really-hard",s:"A company wants true micro-segmentation for east-west traffic. Which technology is MOST appropriate?",o:["Traditional VLANs only","Physical air-gapping of every server","Software-defined networking or host-based micro-segmentation","MAC address filtering only"],c:2,x:"La micro-segmentation moderne s'appuie sur SDN ou des solutions host-based.",r:"Les VLANs classiques ont des limites pour une segmentation fine."},

// ===== DOMAIN 3 – 40 NEW QUESTIONS (Hard + Really Hard only) =====

{d:3,e:"hard",s:"Which cloud service model places the greatest security responsibility on the customer?",o:["PaaS","SaaS","IaaS","FaaS"],c:2,x:"En IaaS le client a le plus de responsabilités (OS, middleware, applications, données, identités).",r:"En SaaS le fournisseur porte la plus grande partie de la responsabilité."},
{d:3,e:"hard",s:"Which architecture evaluates every access request regardless of the user’s network location?",o:["Traditional perimeter security","Flat trusted internal network","Zero Trust","VPN-centric access only"],c:2,x:"Zero Trust évalue chaque requête indépendamment de la localisation réseau.",r:"Le modèle périmétrique fait confiance à ce qui est à l'intérieur."},
{d:3,e:"hard",s:"Placing administrative interfaces on a dedicated network with no direct internet access is an example of:",o:["In-band management","Out-of-band management","Management through the production network","Internet-exposed management"],c:1,x:"La gestion hors bande (out-of-band) isole les interfaces d'administration.",r:"La gestion in-band utilise le réseau de production."},
{d:3,e:"hard",s:"Which technology provides the strongest isolation by giving each virtual machine its own kernel?",o:["Containers","Process isolation only","Type 1 hypervisor","Application sandboxing only"],c:2,x:"Les hyperviseurs de Type 1 offrent une isolation forte grâce à un noyau séparé par VM.",r:"Les conteneurs partagent le noyau de l'hôte."},
{d:3,e:"hard",s:"Why should database servers generally have no direct route to the internet?",o:["To improve query performance","To simplify IP addressing","To reduce the attack surface and limit data exfiltration paths","To make backups faster"],c:2,x:"Empêcher l'accès internet direct depuis les bases de données réduit la surface d'attaque et les possibilités d'exfiltration.",r:"Ce n'est pas principalement pour la performance."},
{d:3,e:"hard",s:"Which approach is most aligned with Zero Trust for remote access to internal applications?",o:["Traditional VPN that places the user directly on the internal network","Direct exposure of applications to the internet with only a WAF","ZTNA that grants access only to specific applications after continuous verification","IP whitelisting of all possible remote user addresses"],c:2,x:"ZTNA limite l'accès à l'application spécifique après vérification continue de l'identité et de la posture.",r:"Le VPN traditionnel donne souvent un accès réseau trop large."},
{d:3,e:"hard",s:"What is the main security benefit of a hub-and-spoke network design where all traffic passes through a central security stack?",o:["Maximum performance with lowest latency","Consistent inspection and control of east-west traffic","Complete elimination of the need for endpoint security","Simplified routing without any security benefit"],c:1,x:"Forcer le trafic via un point central permet une inspection et un contrôle cohérents du trafic est-ouest.",r:"Ce n'est pas pour minimiser la latence."},
{d:3,e:"hard",s:"Which security advantage does infrastructure-as-code primarily provide?",o:["Easier unrestricted manual changes in production","Version control, peer review, consistency and reduced configuration drift","Elimination of the need for any access control","Guarantee that no vulnerabilities will ever exist"],c:1,x:"L'IaC permet le contrôle de version, la revue par les pairs et réduit le drift de configuration.",r:"Elle ne rend pas les changements manuels plus faciles."},
{d:3,e:"hard",s:"Why must container privileges be carefully managed?",o:["Containers are completely isolated like full virtual machines","Containers share the host kernel; excessive privileges increase the risk of container escape","Containers cannot be given any privileges at all","Privileges have no security impact inside containers"],c:1,x:"Les conteneurs partagent le noyau de l'hôte, donc des privilèges excessifs augmentent le risque d'évasion.",r:"Ils ne sont pas isolés aussi fortement que des machines virtuelles."},
{d:3,e:"hard",s:"Requiring administrative access to go through a hardened jump server or privileged access workstation primarily supports:",o:["Maximum convenience for administrators","Reduced attack surface and controlled, monitored administrative pathways","Elimination of the need for multi-factor authentication","Direct internet access from production systems"],c:1,x:"Les jump servers / PAW réduisent la surface d'attaque et imposent des chemins d'administration contrôlés et audités.",r:"Ils ne visent pas le confort maximal des administrateurs."},
{d:3,e:"hard",s:"Which design best reduces the risk that a compromised web application leads to full infrastructure compromise?",o:["Running the application as root on the host","Giving the application direct access to the hypervisor","Strong isolation and least privilege between application, OS and management layers","Placing management tools on the same server as the application"],c:2,x:"L'isolation et le moindre privilège entre les couches limitent la progression d'un attaquant.",r:"Exécuter l'application en root augmente fortement le risque."},
{d:3,e:"hard",s:"Which technology is commonly used to create isolated virtual networks on top of shared physical infrastructure?",o:["Physical separation only","MAC address filtering only","Network virtualisation overlays (such as VXLAN)","Port security only"],c:2,x:"Les overlays de virtualisation réseau (VXLAN, etc.) permettent d'isoler des réseaux logiques sur une infrastructure partagée.",r:"La séparation physique pure n'est pas toujours possible ou scalable."},
{d:3,e:"hard",s:"Why is mutual TLS (mTLS) often preferred over simple API keys for service-to-service authentication?",o:["API keys are always more secure and easier to manage","mTLS provides cryptographic mutual authentication and is more resistant to credential theft and replay","mTLS eliminates the need for any authorization checks","API keys automatically provide non-repudiation"],c:1,x:"mTLS authentifie mutuellement les deux services de façon cryptographique et résiste mieux au vol de credentials.",r:"Les clés API sont plus faciles à voler et à rejouer."},
{d:3,e:"hard",s:"Requiring production Kubernetes nodes to communicate externally only through controlled egress gateways primarily supports:",o:["Maximum convenience for developers pulling images","Reduced attack surface and better control and detection of outbound traffic","Elimination of the need for network policies","Acceptance of unrestricted outbound access"],c:1,x:"Contrôler le trafic sortant réduit la surface d'attaque et facilite la détection d'exfiltration ou de C2.",r:"Ce n'est pas pour maximiser le confort des développeurs."},
{d:3,e:"hard",s:"Which statement about Type 1 hypervisors versus containers is most accurate regarding isolation?",o:["Containers always provide stronger isolation than Type 1 hypervisors","Type 1 hypervisors generally provide stronger isolation because each VM has its own guest kernel","There is no meaningful difference in isolation strength","Type 1 hypervisors are inherently less secure because of their complexity"],c:1,x:"Les hyperviseurs de Type 1 offrent généralement une meilleure isolation grâce à des noyaux séparés.",r:"Les conteneurs partagent le noyau de l'hôte."},
{d:3,e:"hard",s:"Why should management interfaces of network devices not be accessible from the general user network?",o:["To improve routing performance","To simplify cabling","To reduce the likelihood that a compromised user device can attack management interfaces","To allow users to manage the devices themselves"],c:2,x:"Séparer les réseaux de gestion et utilisateurs limite les possibilités d'attaque depuis des postes compromis.",r:"Ce n'est pas pour simplifier le câblage."},
{d:3,e:"hard",s:"Which architecture pattern treats every network location as potentially hostile and evaluates each request individually?",o:["Traditional castle-and-moat perimeter security","Flat trusted internal network","Zero Trust","VPN-centric remote access only"],c:2,x:"Zero Trust considère chaque emplacement réseau comme non fiable et évalue chaque requête.",r:"Le modèle château-fort fait confiance à tout ce qui est à l'intérieur du périmètre."},
{d:3,e:"hard",s:"A company implements strict network segmentation between development, test and production environments. The main security benefit is:",o:["Maximum ease of moving code between environments","Limiting the impact of a compromise in one environment on the others","Elimination of the need for access control","Simplified IP addressing schemes only"],c:1,x:"La segmentation entre environnements limite la propagation d'une compromission.",r:"Ce n'est pas pour faciliter les déplacements de code."},
{d:3,e:"hard",s:"Which design choice best reduces the risk of a compromised workload accessing cloud instance metadata for credentials?",o:["Giving every workload full administrative rights","Disabling all logging","Restricting or carefully controlling access to the metadata service (e.g. IMDSv2 + network policies)","Exposing the metadata service to the internet"],c:2,x:"Restreindre l'accès au service de métadonnées limite le vol de credentials temporaires.",r:"Donner des droits admin à toutes les charges de travail augmente le risque."},
{d:3,e:"hard",s:"Which approach is most aligned with secure design for highly privileged administrative activities?",o:["Performing admin tasks from any regular user workstation","Sharing a single high-privilege account among many administrators","Use of dedicated hardened privileged access workstations and just-in-time access","Allowing permanent standing privileges for convenience"],c:2,x:"Des postes d'administration dédiés (PAW) et des accès just-in-time réduisent les risques liés aux privilèges élevés.",r:"Administrer depuis un poste utilisateur normal augmente fortement la surface d'attaque."},

{d:3,e:"really-hard",s:"In a Zero Trust architecture, which statement about the network is most accurate?",o:["Internal networks are fully trusted once the user is authenticated","A VPN connection is sufficient to grant broad internal access","The network is considered hostile by default and every request is evaluated regardless of location","Micro-segmentation is unnecessary if identity verification is strong"],c:2,x:"En Zero Trust, le réseau est considéré comme hostile par défaut et chaque requête est évaluée.",r:"La confiance basée sur la localisation réseau est précisément ce que Zero Trust rejette."},
{d:3,e:"really-hard",s:"Which cloud service model places the greatest responsibility on the customer for security configuration and management of the underlying infrastructure?",o:["SaaS","PaaS","IaaS","FaaS"],c:2,x:"En IaaS le client gère l'OS, le middleware, les applications, les identités et les données.",r:"SaaS place la plus grande partie de la responsabilité sur le fournisseur."},
{d:3,e:"really-hard",s:"A company wants true micro-segmentation for east-west traffic inside a data centre. Which technology is most appropriate?",o:["Traditional VLANs only","Physical air-gapping of every server","Software-defined networking or host-based micro-segmentation solutions","MAC address filtering only"],c:2,x:"La micro-segmentation moderne s'appuie sur SDN ou des solutions host-based / zero-trust overlays.",r:"Les VLANs classiques ont des limites pour une segmentation fine et scalable."},
{d:3,e:"really-hard",s:"Which architecture enforces access decisions based on identity, device posture and context rather than network location?",o:["Traditional remote-access VPN concentrator","DMZ with reverse proxy only","Zero Trust Network Access (ZTNA) / SASE","Port-based 802.1X only"],c:2,x:"ZTNA et SASE appliquent des politiques basées sur l'identité, la posture et le contexte.",r:"Le VPN classique donne souvent un accès trop large une fois la connexion établie."},
{d:3,e:"really-hard",s:"In a shared-responsibility model for a PaaS offering, which security task remains most clearly the customer’s responsibility?",o:["Physical security of the data centre","Hardware maintenance of the underlying servers","Proper configuration of the application, data protection, and identity and access management for the application","Hypervisor patching"],c:2,x:"En PaaS le client reste responsable de l'application, des données et de la gestion des identités applicatives.",r:"Le fournisseur gère l'infrastructure sous-jacente."},
{d:3,e:"really-hard",s:"Placing web servers in a DMZ while keeping databases on a separate, highly restricted internal segment best illustrates:",o:["Flat network design","Maximum convenience for developers","Network segmentation and defence in depth","Complete trust of all internal traffic"],c:2,x:"Séparer les serveurs web et les bases de données illustre la segmentation et la défense en profondeur.",r:"Un réseau plat permettrait une communication libre entre les deux."},
{d:3,e:"really-hard",s:"A security architect requires that all administrative interfaces of network devices are only reachable from a dedicated management network that has no direct internet access. This is an example of:",o:["In-band management for simplicity","Maximum exposure of management interfaces","Out-of-band management and reduced attack surface","Risk acceptance of internet-facing management"],c:2,x:"La gestion hors bande réduit fortement la surface d'attaque des interfaces d'administration.",r:"La gestion in-band expose davantage ces interfaces."},
{d:3,e:"really-hard",s:"Which technology allows multiple virtual networks to share the same physical infrastructure while maintaining strong logical isolation?",o:["Simple VLAN trunking without any other controls","Physical separation only","Network virtualisation / VXLAN or similar overlay technologies","MAC address filtering only"],c:2,x:"Les technologies de virtualisation réseau (VXLAN, etc.) permettent l'isolation logique sur une infrastructure partagée.",r:"Les VLANs seuls ont des limites d'échelle et de sécurité."},
{d:3,e:"really-hard",s:"Why is a jump server or privileged access workstation often required for administrative access in high-security environments?",o:["To make administration as convenient as possible","To eliminate the need for multi-factor authentication","To reduce the attack surface and enforce controlled, monitored administrative pathways","To allow direct internet access from production servers"],c:2,x:"Les jump servers / PAW réduisent la surface d'attaque et imposent des chemins d'administration contrôlés.",r:"Ils ne visent pas le confort maximal des administrateurs."},
{d:3,e:"really-hard",s:"Which statement about container security architecture is most accurate?",o:["Each container runs a completely separate kernel","Containers provide the same isolation level as full virtual machines","Containers share the host kernel, so a kernel vulnerability can potentially affect all containers on the host","Container escape is theoretically impossible"],c:2,x:"Les conteneurs partagent le noyau de l'hôte, ce qui crée une surface d'attaque différente de celle des machines virtuelles.",r:"Les VMs ont un noyau séparé grâce à l'hyperviseur."},

{d:3,e:"hard",s:"A company requires that all production changes are made via infrastructure-as-code pipelines with mandatory peer review. This primarily supports:",o:["Maximum speed of unreviewed changes","Consistency, auditability and reduced risk of unauthorised or erroneous changes","Elimination of the need for testing","Complete freedom for developers to change production directly"],c:1,x:"Les pipelines IaC avec revue améliorent la cohérence, l'auditabilité et réduisent les risques de changements non autorisés.",r:"Ce n'est pas pour maximiser la vitesse des changements non revus."},
{d:3,e:"hard",s:"Which security benefit does a well-implemented DMZ provide?",o:["It completely eliminates the need for firewalls","It makes the internal network fully trusted","It allows controlled exposure of services while limiting direct access to the internal network","It removes the need for authentication"],c:2,x:"La DMZ permet d'exposer des services de manière contrôlée tout en protégeant le réseau interne.",r:"Elle n'élimine pas le besoin de firewalls."},
{d:3,e:"hard",s:"In a secure architecture, why is it recommended to avoid placing management interfaces on the same network as user traffic?",o:["To improve user experience","To simplify cabling","To reduce the likelihood that a compromised user device can attack management interfaces","To allow users to manage devices more easily"],c:2,x:"Séparer les réseaux de gestion et utilisateurs limite les attaques depuis des postes compromis.",r:"Ce n'est pas pour simplifier le câblage."},
{d:3,e:"hard",s:"Which technology is commonly used to enforce identity-aware access to applications regardless of the user’s network location?",o:["Traditional VPN only","Simple IP-based firewall rules only","Zero Trust Network Access (ZTNA) or SASE solutions","Port-based network access control only"],c:2,x:"ZTNA/SASE appliquent des politiques basées sur l'identité indépendamment de la localisation réseau.",r:"Les règles IP classiques dépendent fortement de la localisation."},
{d:3,e:"hard",s:"A security architect insists that production data stores must not be directly accessible from developer workstations. This is an application of:",o:["Flat network design","Maximum convenience for developers","Network segmentation and least privilege","Complete trust of internal users"],c:2,x:"Empêcher l'accès direct des postes de développement aux données de production applique la segmentation et le moindre privilège.",r:"Ce n'est pas pour le confort des développeurs."},
{d:3,e:"really-hard",s:"Which design principle is most clearly demonstrated by using separate identity systems or strong isolation between administrative and regular user accounts?",o:["Maximum convenience through shared accounts","Elimination of the need for authentication","Separation of privileges and reduced impact of account compromise","Complete trust of all internal accounts"],c:2,x:"Séparer les comptes administratifs et utilisateurs réduit l'impact d'une compromission de compte.",r:"Les comptes partagés augmentent fortement le risque."},
{d:3,e:"hard",s:"In a secure multi-tier architecture, why are web servers often placed in a different network segment from application and database servers?",o:["To maximise network performance","To simplify certificate management","To apply different security controls and limit the impact of a web-tier compromise","To eliminate the need for encryption"],c:2,x:"Séparer les tiers permet d'appliquer des contrôles de sécurité différents et de limiter la propagation d'une compromission.",r:"Ce n'est pas principalement pour la performance."},
{d:3,e:"really-hard",s:"A container is running with the --privileged flag and has access to the host’s Docker socket. What is the most severe risk?",o:["Only denial of service inside the container","Only limited file read access on the host","Container escape leading to full host compromise","No significant risk because containers are isolated by design"],c:2,x:"Un conteneur privilégié avec accès au socket Docker peut facilement s'échapper et compromettre l'hôte entier.",r:"Les conteneurs ne sont pas isolés de façon absolue."},
{d:3,e:"hard",s:"Which of the following is a key security benefit of using a Type 1 hypervisor?",o:["It completely eliminates the need for guest OS patching","It provides strong isolation between virtual machines through hardware-assisted virtualisation","It makes all virtual machines share the same kernel for performance","It removes the need for any network segmentation"],c:1,x:"Les hyperviseurs de Type 1 offrent une isolation forte entre les VMs grâce à la virtualisation assistée par le matériel.",r:"Ils n'éliminent pas le besoin de patcher les OS invités."},
{d:3,e:"really-hard",s:"In a mature Zero Trust deployment, what is continuously evaluated rather than trusted after initial authentication?",o:["Only the user’s password strength at login time","Only the source IP address of the request","User identity, device posture, location and risk signals for every request","Only the time of day the request is made"],c:2,x:"Zero Trust évalue en continu l'identité, la posture de l'appareil et les signaux de risque à chaque requête.",r:"Une vérification uniquement au moment du login n'est pas suffisante."},

// ===== DOMAIN 3 – 40 NEW QUESTIONS (Hard + Really Hard only) =====

{d:3,e:"hard",s:"Which cloud model requires the customer to manage the operating system, runtime and applications?",o:["SaaS","PaaS","IaaS","FaaS"],c:2,x:"En IaaS le client est responsable de l'OS, du runtime et des applications.",r:"En SaaS le fournisseur gère presque tout."},
{d:3,e:"hard",s:"Which security model assumes that no network location should be automatically trusted?",o:["Traditional perimeter security","Flat network architecture","Zero Trust","VPN-centric architecture"],c:2,x:"Zero Trust ne fait aucune confiance implicite basée sur la localisation réseau.",r:"Le modèle périmétrique fait confiance à l'intérieur du réseau."},
{d:3,e:"hard",s:"Placing management interfaces on a separate network that has no internet connectivity is an example of:",o:["In-band management","Out-of-band management","Production network management","Internet-facing management"],c:1,x:"La gestion hors bande isole les interfaces d'administration sur un réseau dédié.",r:"La gestion in-band utilise le réseau de production."},
{d:3,e:"hard",s:"Which virtualisation technology provides each virtual machine with its own dedicated kernel?",o:["Containers","Process isolation","Type 1 hypervisor","Application sandbox"],c:2,x:"Les hyperviseurs de Type 1 offrent à chaque VM son propre noyau.",r:"Les conteneurs partagent le noyau de l'hôte."},
{d:3,e:"hard",s:"Why is it recommended that database servers do not have direct internet access?",o:["To improve database performance","To simplify addressing","To reduce attack surface and limit exfiltration paths","To speed up backups"],c:2,x:"L'absence d'accès internet direct réduit la surface d'attaque et les risques d'exfiltration.",r:"Ce n'est pas une question de performance."},
{d:3,e:"hard",s:"Which solution grants access only to specific applications after verifying identity and device posture continuously?",o:["Traditional VPN","Reverse proxy only","Zero Trust Network Access (ZTNA)","IP allow-listing"],c:2,x:"ZTNA donne accès uniquement à l'application demandée après vérification continue.",r:"Le VPN traditionnel place souvent l'utilisateur sur le réseau interne."},
{d:3,e:"hard",s:"What is the main security advantage of forcing all inter-segment traffic through a central inspection point?",o:["Lower latency","Consistent policy enforcement and visibility","Elimination of endpoint security","Simpler routing only"],c:1,x:"Un point d'inspection central permet d'appliquer et de contrôler les politiques de façon cohérente.",r:"Ce n'est pas pour réduire la latence."},
{d:3,e:"hard",s:"What security benefit does Infrastructure as Code primarily provide?",o:["Faster manual changes in production","Version control, reviewability and reduced configuration drift","Removal of all access controls","Guaranteed absence of vulnerabilities"],c:1,x:"L'IaC apporte le contrôle de version, la revue et limite le drift de configuration.",r:"Elle ne rend pas les changements manuels plus faciles."},
{d:3,e:"hard",s:"Why is running containers with excessive privileges particularly dangerous?",o:["Containers are fully isolated like virtual machines","Containers share the host kernel, increasing the risk of container escape","Containers cannot have privileges","Privileges have no effect inside containers"],c:1,x:"Les conteneurs partagent le noyau de l'hôte, donc des privilèges élevés facilitent une évasion vers l'hôte.",r:"Ils ne sont pas isolés comme des machines virtuelles."},
{d:3,e:"hard",s:"Requiring administrators to use a hardened jump host or privileged access workstation mainly supports:",o:["Administrator convenience","Reduced attack surface and controlled administrative access","Removal of multi-factor authentication","Direct internet access from production"],c:1,x:"Les jump hosts / PAW réduisent la surface d'attaque des accès administratifs.",r:"Ils ne visent pas le confort des administrateurs."},
{d:3,e:"hard",s:"Which design most effectively limits the damage if a web application is compromised?",o:["Running the application as root","Giving the application hypervisor access","Strong segmentation and least privilege between tiers","Placing management tools on the same server"],c:2,x:"La segmentation et le moindre privilège entre les couches limitent la progression de l'attaquant.",r:"Exécuter l'application en root augmente le risque."},
{d:3,e:"hard",s:"Which technology is commonly used to create logically isolated networks over shared physical infrastructure?",o:["Physical separation only","MAC filtering only","Network virtualisation overlays (e.g. VXLAN)","Port security only"],c:2,x:"Les overlays de virtualisation réseau permettent d'isoler des réseaux logiques sur une infrastructure partagée.",r:"La séparation physique pure n'est pas toujours possible."},
{d:3,e:"hard",s:"Why is mutual TLS preferred over static API keys for service-to-service communication?",o:["API keys are more secure","mTLS provides mutual cryptographic authentication and better resistance to theft","mTLS removes the need for authorization","API keys provide non-repudiation by default"],c:1,x:"mTLS authentifie mutuellement les deux parties de façon cryptographique.",r:"Les clés API sont plus faciles à voler et à rejouer."},
{d:3,e:"hard",s:"Forcing Kubernetes nodes to use controlled egress gateways mainly provides:",o:["Easier image pulling for developers","Reduced attack surface and better outbound traffic control","Removal of network policies","Unrestricted outbound access"],c:1,x:"Le contrôle de l'egress réduit la surface d'attaque et améliore la détection du trafic sortant suspect.",r:"Ce n'est pas pour le confort des développeurs."},
{d:3,e:"hard",s:"Which statement correctly compares Type 1 hypervisors and containers regarding isolation?",o:["Containers always provide stronger isolation","Type 1 hypervisors generally provide stronger isolation because each VM has its own kernel","There is no difference in isolation","Type 1 hypervisors are less secure"],c:1,x:"Les hyperviseurs de Type 1 offrent généralement une meilleure isolation grâce à des noyaux séparés.",r:"Les conteneurs partagent le noyau de l'hôte."},
{d:3,e:"hard",s:"Why should network device management interfaces not be reachable from user networks?",o:["To improve routing speed","To simplify cabling","To prevent compromised user devices from attacking management interfaces","To allow users to manage devices"],c:2,x:"Séparer les interfaces de gestion limite les attaques provenant de postes utilisateurs compromis.",r:"Ce n'est pas une question de performance de routage."},
{d:3,e:"hard",s:"Which architecture treats every network location as untrusted by default?",o:["Castle-and-moat perimeter model","Flat trusted network","Zero Trust","VPN-only access"],c:2,x:"Zero Trust considère chaque emplacement comme non fiable par défaut.",r:"Le modèle périmétrique fait confiance à l'intérieur."},
{d:3,e:"hard",s:"Strict segmentation between development, testing and production environments mainly provides:",o:["Easier code promotion","Limitation of the impact of a compromise in one environment","Removal of access controls","Simpler IP management"],c:1,x:"La segmentation entre environnements limite la propagation d'une compromission.",r:"Ce n'est pas pour faciliter les déplacements de code."},
{d:3,e:"hard",s:"Which control best prevents a compromised cloud workload from stealing credentials via the metadata service?",o:["Giving all workloads admin rights","Disabling logging","Restricting access to the instance metadata service","Exposing the metadata service publicly"],c:2,x:"Restreindre l'accès au service de métadonnées empêche le vol de credentials temporaires.",r:"Donner des droits admin à toutes les charges augmente le risque."},
{d:3,e:"hard",s:"Which practice is most aligned with secure administrative access?",o:["Using regular workstations for admin tasks","Sharing a single high-privilege account","Using dedicated privileged access workstations and just-in-time access","Granting permanent elevated privileges"],c:2,x:"Des postes d'administration dédiés et des accès just-in-time réduisent les risques.",r:"Administrer depuis un poste standard augmente la surface d'attaque."},

{d:3,e:"really-hard",s:"In a Zero Trust architecture, which statement is most accurate?",o:["Internal networks are trusted after authentication","A VPN connection grants broad internal access","The network is considered hostile and every request is evaluated","Micro-segmentation is unnecessary if identity is verified"],c:2,x:"En Zero Trust le réseau est considéré comme hostile et chaque requête est évaluée individuellement.",r:"La confiance basée sur la localisation est rejetée."},
{d:3,e:"really-hard",s:"Which cloud service model places the highest security responsibility on the customer?",o:["SaaS","PaaS","IaaS","FaaS"],c:2,x:"L'IaaS laisse au client la plus grande part de responsabilité de sécurité.",r:"Le SaaS place la majorité de la responsabilité sur le fournisseur."},
{d:3,e:"really-hard",s:"A company needs fine-grained control of east-west traffic inside the data centre. Which technology is most suitable?",o:["Traditional VLANs only","Physical isolation of every server","Software-defined networking or host-based micro-segmentation","MAC address filtering only"],c:2,x:"La micro-segmentation moderne repose sur SDN ou des solutions host-based.",r:"Les VLANs classiques sont limités pour une segmentation fine."},
{d:3,e:"really-hard",s:"Which solution makes access decisions based on identity, device posture and context rather than network location?",o:["Classic remote access VPN","DMZ reverse proxy only","Zero Trust Network Access / SASE","802.1X port-based access only"],c:2,x:"ZTNA/SASE basent les décisions d'accès sur l'identité et le contexte.",r:"Le VPN classique se base surtout sur la connexion réseau."},
{d:3,e:"really-hard",s:"In a PaaS model, which responsibility remains clearly with the customer?",o:["Physical data centre security","Hardware maintenance","Application configuration, data protection and identity management","Hypervisor patching"],c:2,x:"En PaaS le client reste responsable de l'application, des données et des identités.",r:"Le fournisseur gère l'infrastructure sous-jacente."},
{d:3,e:"really-hard",s:"Placing public web servers in a DMZ and databases in a restricted internal segment best demonstrates:",o:["Flat network design","Developer convenience","Network segmentation and defence in depth","Full trust of internal traffic"],c:2,x:"Cette séparation illustre la segmentation et la défense en profondeur.",r:"Un réseau plat permettrait une communication directe."},
{d:3,e:"really-hard",s:"Requiring that all network device administration occurs only from a dedicated management network is an example of:",o:["In-band management","Maximum management exposure","Out-of-band management","Acceptance of internet-facing management"],c:2,x:"La gestion hors bande réduit fortement la surface d'attaque des interfaces d'administration.",r:"La gestion in-band expose davantage ces interfaces."},
{d:3,e:"really-hard",s:"Which technology allows multiple isolated virtual networks to run on shared physical infrastructure?",o:["Simple VLAN trunking only","Physical separation only","Network virtualisation overlays such as VXLAN","MAC filtering only"],c:2,x:"Les overlays de virtualisation réseau permettent une isolation logique sur une infrastructure partagée.",r:"Les VLANs seuls ont des limites d'échelle et de sécurité."},
{d:3,e:"really-hard",s:"Why are privileged access workstations recommended for administrative tasks?",o:["To maximise administrator convenience","To eliminate multi-factor authentication","To reduce attack surface and enforce controlled administrative paths","To allow production servers direct internet access"],c:2,x:"Les PAW réduisent la surface d'attaque et imposent des chemins d'administration contrôlés.",r:"Ils ne visent pas le confort maximal."},
{d:3,e:"really-hard",s:"Which statement about containers is most accurate from a security perspective?",o:["Each container has its own separate kernel","Containers offer the same isolation as virtual machines","Containers share the host kernel, so a kernel exploit can affect all containers","Container escape is impossible"],c:2,x:"Les conteneurs partagent le noyau de l'hôte, ce qui crée une surface d'attaque différente des VMs.",r:"Les machines virtuelles ont des noyaux séparés."},

{d:3,e:"hard",s:"Requiring all production changes to go through Infrastructure-as-Code pipelines with peer review mainly supports:",o:["Faster unreviewed changes","Consistency, auditability and reduced risk of unauthorised changes","Removal of testing requirements","Direct production access for all developers"],c:1,x:"Les pipelines IaC avec revue améliorent la cohérence et réduisent les changements non autorisés.",r:"Ce n'est pas pour accélérer les changements non revus."},
{d:3,e:"hard",s:"What is the main security benefit of a properly designed DMZ?",o:["It removes the need for firewalls","It makes the internal network fully trusted","It allows controlled exposure of services while protecting the internal network","It eliminates authentication requirements"],c:2,x:"La DMZ permet d'exposer certains services tout en protégeant le réseau interne.",r:"Elle n'élimine pas le besoin de firewalls."},
{d:3,e:"hard",s:"Why is it recommended to keep management interfaces off the user network?",o:["To improve user experience","To simplify physical cabling","To reduce the chance that a compromised user device can reach management interfaces","To let users manage the devices"],c:2,x:"Séparer les réseaux de gestion limite les attaques depuis des postes utilisateurs.",r:"Ce n'est pas pour simplifier le câblage."},
{d:3,e:"hard",s:"Which technology enforces access to applications based on identity regardless of user location?",o:["Traditional VPN only","IP-based firewall rules only","Zero Trust Network Access or SASE","Port-based NAC only"],c:2,x:"ZTNA/SASE appliquent des politiques basées sur l'identité indépendamment de la localisation.",r:"Les règles IP dépendent fortement de l'emplacement réseau."},
{d:3,e:"hard",s:"Preventing developer workstations from having direct access to production databases is an application of:",o:["Flat network design","Developer convenience","Network segmentation and least privilege","Full trust of internal users"],c:2,x:"Cette séparation applique la segmentation et le principe du moindre privilège.",r:"Ce n'est pas pour le confort des développeurs."},
{d:3,e:"really-hard",s:"Using separate identity systems or strong isolation between admin and standard user accounts best demonstrates:",o:["Shared account convenience","Removal of authentication needs","Separation of privileges and reduced impact of compromise","Full trust of all internal accounts"],c:2,x:"Séparer les comptes admin et utilisateurs réduit l'impact d'une compromission.",r:"Les comptes partagés augmentent le risque."},
{d:3,e:"hard",s:"Why are web servers often placed in a different segment from application and database servers?",o:["To maximise performance","To simplify certificates","To apply different security controls and limit the blast radius of a web compromise","To remove the need for encryption"],c:2,x:"La séparation des tiers permet d'appliquer des contrôles différents et de limiter la propagation d'une attaque.",r:"Ce n'est pas principalement pour la performance."},
{d:3,e:"really-hard",s:"A container running with --privileged and access to the Docker socket creates which major risk?",o:["Only internal denial of service","Only limited file read access","Container escape leading to host compromise","No real risk because of container isolation"],c:2,x:"Un conteneur privilégié avec accès au socket Docker peut s'échapper et prendre le contrôle de l'hôte.",r:"Les conteneurs n'offrent pas une isolation absolue."},
{d:3,e:"hard",s:"What is a key security benefit of a Type 1 hypervisor?",o:["It removes the need to patch guest operating systems","It provides strong isolation between virtual machines","It forces all VMs to share the same kernel","It eliminates the need for network segmentation"],c:1,x:"Les hyperviseurs de Type 1 offrent une isolation forte entre les machines virtuelles.",r:"Ils n'éliminent pas le besoin de patcher les OS invités."},
{d:3,e:"really-hard",s:"In a mature Zero Trust implementation, what is continuously evaluated?",o:["Only password strength at login","Only the source IP address","Identity, device posture and request context on every access","Only the time of the request"],c:2,x:"Zero Trust évalue en continu l'identité, la posture de l'appareil et le contexte de chaque requête.",r:"Une vérification uniquement au login n'est pas suffisante."},

// ====================== DOMAIN 4 ======================
{d:4,e:"medium",s:"Which tool is commonly used to capture and analyse network packets?",o:["Nmap","John the Ripper","Wireshark","Hashcat"],c:2,x:"Wireshark permet de capturer et d'analyser les paquets réseau.",r:"Nmap est un scanner de ports."},
{d:4,e:"medium",s:"What is the first phase of the NIST incident response lifecycle?",o:["Detection and Analysis","Containment","Preparation","Recovery"],c:2,x:"La première phase du cycle NIST est la Préparation.",r:"La détection vient ensuite."},
{d:4,e:"medium",s:"Which Windows event ID records a successful logon?",o:["4625","4648","4624","4672"],c:2,x:"L'événement 4624 correspond à une connexion réussie.",r:"4625 correspond à un échec de connexion."},

{d:4,e:"hard",s:"Which metric best measures how long an attacker was active before being detected?",o:["Mean Time to Respond (MTTR)","Mean Time Between Failures","Dwell time / Mean Time to Detect (MTTD)","Recovery Time Objective"],c:2,x:"Le dwell time (ou MTTD) mesure le temps entre le début de l'attaque et sa détection.",r:"MTTR mesure le temps de réponse après détection."},
{d:4,e:"hard",s:"What should be the FIRST priority during active ransomware encryption?",o:["Immediately wipe all affected disks","Wait until encryption finishes","Isolate affected systems to stop further encryption and spread","Shut down the entire network"],c:2,x:"Isoler les systèmes touchés limite les dégâts supplémentaires.",r:"Un wipe immédiat détruit des preuves."},
{d:4,e:"hard",s:"Which phase of incident response involves removing malware and closing exploited vulnerabilities?",o:["Containment","Recovery","Eradication","Detection"],c:2,x:"L'éradication consiste à éliminer la cause de l'incident.",r:"La recovery restaure les systèmes."},
{d:4,e:"hard",s:"Clearing or disabling Windows Event Logs on multiple systems is best classified as:",o:["Initial access technique","Privilege escalation only","Anti-forensics / defence evasion","Data exfiltration only"],c:2,x:"La suppression ou désactivation des journaux est une technique anti-forensique classique.",r:"Ce n'est pas de l'accès initial."},
{d:4,e:"hard",s:"Which combination is most effective for detecting credential dumping from LSASS?",o:["Only traditional antivirus signatures","Only network traffic analysis","EDR monitoring of LSASS access + Credential Guard","Only failed logon monitoring"],c:2,x:"La surveillance EDR de LSASS combinée à Credential Guard est la plus efficace.",r:"Les signatures AV classiques sont souvent insuffisantes."},
{d:4,e:"hard",s:"Automatic isolation of a host, disabling an account and creating a ticket is an example of:",o:["Manual analysis only","Vulnerability scanning","Security orchestration and automated response","Penetration testing"],c:2,x:"C'est de l'orchestration et de l'automatisation de la réponse (SOAR).",r:"Ce n'est pas un scan de vulnérabilités."},

{d:4,e:"really-hard",s:"An attacker has been using a Golden Ticket for several months. What is the MOST critical recovery action?",o:["Only reset the passwords of currently logged-in users","Only reboot all Domain Controllers","Reset the KRBTGT account password twice and carefully plan domain recovery","Only delete the ticket from memory on one machine"],c:2,x:"Un Golden Ticket nécessite de réinitialiser deux fois le mot de passe du compte KRBTGT.",r:"Un simple redémarrage des DC ne suffit pas."},
{d:4,e:"really-hard",s:"You observe LSASS access from an unusual process followed by a new service running from a user-writable directory. This MOST strongly indicates:",o:["Legitimate antivirus scanning","Windows Update activity","Credential dumping followed by persistence establishment","Simple software installation"],c:2,x:"L'accès à LSASS suivi de la création d'un service suspect est un enchaînement classique de dumping + persistance.",r:"Ce n'est pas une activité de mise à jour Windows."},
{d:4,e:"really-hard",s:"Which combination is MOST effective for detecting living-off-the-land lateral movement?",o:["Detailed process creation + authentication logs + network connections","Only antivirus alerts","Only firewall deny logs","Only DNS query volume"],c:0,x:"La combinaison processus + authentification + réseau est la plus efficace contre le mouvement latéral LotL.",r:"Les alertes AV traditionnelles sont souvent insuffisantes."},

// ===== DOMAIN 4 – 40 NEW QUESTIONS (Hard + Really Hard only) =====

{d:4,e:"hard",s:"Which metric best measures how long an attacker was present in the environment before being detected?",o:["Mean Time to Respond (MTTR)","Mean Time Between Failures (MTBF)","Dwell time / Mean Time to Detect (MTTD)","Recovery Time Objective (RTO)"],c:2,x:"Le dwell time (ou MTTD) mesure le temps entre le début de l'attaque et sa détection.",r:"MTTR mesure le temps de réponse après la détection."},
{d:4,e:"hard",s:"During an active ransomware encryption, what should be the FIRST priority?",o:["Immediately wipe all affected disks","Wait until encryption finishes to measure impact","Isolate affected systems to stop further encryption and lateral movement","Shut down the entire organisation network"],c:2,x:"Isoler rapidement les systèmes touchés limite la propagation et le chiffrement supplémentaire.",r:"Un wipe immédiat détruit des preuves et peut être trop radical."},
{d:4,e:"hard",s:"Which phase of the incident response process involves removing malware, closing vulnerabilities and eliminating attacker access?",o:["Containment","Recovery","Eradication","Detection and Analysis"],c:2,x:"L'éradication consiste à éliminer la cause de l'incident (malware, backdoors, failles exploitées).",r:"La recovery restaure les systèmes en production."},
{d:4,e:"hard",s:"Clearing or disabling Windows Event Logs on multiple systems is best classified as:",o:["Initial access technique","Privilege escalation only","Anti-forensics / defence evasion","Data exfiltration only"],c:2,x:"La suppression ou désactivation des journaux est une technique anti-forensique et d'évasion de défense classique.",r:"Ce n'est pas de l'accès initial."},
{d:4,e:"hard",s:"Which combination is most effective for detecting credential dumping from LSASS?",o:["Only traditional antivirus signatures","Only network traffic analysis","EDR monitoring of LSASS access and process injection + Credential Guard where possible","Only monitoring failed logons"],c:2,x:"La surveillance EDR de l'accès à LSASS combinée à Credential Guard est la plus efficace.",r:"Les signatures AV classiques sont souvent insuffisantes contre les outils modernes."},
{d:4,e:"hard",s:"Automatic isolation of a host, disabling of a user account and creation of a high-priority ticket when certain conditions are met is an example of:",o:["Manual analysis only","Vulnerability scanning","Security orchestration and automated response (SOAR)","Penetration testing"],c:2,x:"C'est de l'orchestration et de l'automatisation de la réponse à incident.",r:"Ce n'est pas un scan de vulnérabilités."},
{d:4,e:"hard",s:"To determine the original point of entry of an attacker, the most valuable approach is:",o:["Looking only at the most recent malicious process","Looking only at the last interactive logon","Building a multi-source timeline correlating email, web, remote access and endpoint activity","Looking only at the final payload hash"],c:2,x:"Une timeline multi-sources permet de remonter jusqu'au vecteur d'accès initial.",r:"Se concentrer uniquement sur le payload final ne montre pas le point d'entrée."},
{d:4,e:"hard",s:"To detect attacks that move between on-premises and cloud environments, the most critical capability is:",o:["Only monitoring on-premises Active Directory","Only relying on the cloud provider’s native alerts","Correlated visibility across identity, endpoint, network and cloud control-plane telemetry","Only monitoring the on-premises network perimeter"],c:2,x:"La visibilité corrélée entre on-premises et cloud est essentielle pour détecter les mouvements transverses.",r:"Surveiller un seul environnement laisse des angles morts."},
{d:4,e:"hard",s:"After successfully eradicating a threat, the most important next steps are:",o:["Immediately reduce monitoring levels to save resources","Assume the threat will never return","Validate that systems are clean, restore operations carefully, and monitor closely for re-compromise","Delete all related logs and evidence"],c:2,x:"Il faut valider la propreté des systèmes, restaurer prudemment et surveiller les signes de retour de l'attaquant.",r:"Réduire la surveillance trop tôt est risqué."},
{d:4,e:"hard",s:"Mapping existing detections to the MITRE ATT&CK framework primarily helps to:",o:["Generate compliance reports only","Replace the need for threat hunting","Identify coverage gaps and prioritise new detection development","Reduce the amount of telemetry that needs to be collected"],c:2,x:"Le mapping sur ATT&CK permet d'identifier les trous de couverture et de prioriser le développement de nouvelles détections.",r:"Ce n'est pas uniquement pour de la conformité."},
{d:4,e:"hard",s:"The most effective way to detect abuse of service accounts is to monitor for:",o:["Only the age of the service account password","Only yearly group membership reviews","Interactive logons, unusual access patterns and authentications from unexpected sources","Only the account description field"],c:2,x:"Les comptes de service ne devraient généralement pas avoir de sessions interactives ni d'accès inhabituels.",r:"L'âge du mot de passe ne détecte pas l'usage abusif."},
{d:4,e:"hard",s:"To avoid burning out the core SOC team during a major incident, the most important practice is:",o:["Expecting the same small team to handle unlimited load indefinitely","Avoiding any documentation to move faster","Clear roles, shift structures, escalation paths and predefined surge / external support plans","Focusing only on technical skills without process maturity"],c:2,x:"Des rôles clairs, une organisation en shifts et des plans de montée en charge protègent l'équipe contre le burnout.",r:"Une petite équipe ne peut pas absorber une charge illimitée de façon durable."},
{d:4,e:"hard",s:"The main value of regular purple team exercises is that they:",o:["Only test how well the red team can break in","Only generate more alerts for the blue team","Improve detection and response through collaborative offensive and defensive testing","Replace all other forms of security testing"],c:2,x:"Les exercices purple team font collaborer les équipes offensives et défensives pour améliorer la détection et la réponse.",r:"Ils ne servent pas uniquement à tester l'équipe rouge."},
{d:4,e:"hard",s:"Which activity is most important when preparing for ransomware from an operational perspective?",o:["Only user phishing awareness training","Only increasing antivirus scan frequency","Regularly tested offline or immutable backups combined with network segmentation and rapid isolation capability","Only blocking macros"],c:2,x:"Des sauvegardes testées + segmentation + capacité d'isolation rapide sont critiques opérationnellement contre les ransomwares.",r:"La formation des utilisateurs est importante mais insuffisante seule."},
{d:4,e:"hard",s:"When a high-privilege account is known to be compromised, the most appropriate stance is to:",o:["Only reset the single observed account password","Only monitor without taking containment actions","Assume potential wide impact, carefully reset credentials, and hunt for further activity and persistence","Only notify the account owner"],c:2,x:"Des identifiants privilégiés compromis imposent de considérer un risque de compromission large et d'agir en conséquence.",r:"Réinitialiser un seul compte est souvent insuffisant."},
{d:4,e:"hard",s:"The best way to reconstruct the full sequence of an attack is to:",o:["Use timestamps from only one log source","Trust only the attacker’s own timestamps if available","Build a multi-source timeline correlating endpoint, network, identity and other relevant logs","Use only the time the first alert was generated"],c:2,x:"Une timeline multi-sources est la méthode la plus fiable pour reconstruire le déroulement de l'attaque.",r:"Une seule source de logs est souvent incomplète ou manipulable."},
{d:4,e:"hard",s:"Having a defined process for engaging external incident response support primarily allows a SOC to:",o:["Avoid handling any incidents internally","Permanently replace the internal SOC","Bring in additional expertise and capacity when an incident exceeds internal capabilities","Use external support only for low-severity incidents"],c:2,x:"Un processus clair permet d'obtenir de l'expertise et de la capacité supplémentaires quand la situation dépasse les moyens internes.",r:"Il ne vise pas à éviter de gérer les incidents en interne."},
{d:4,e:"hard",s:"The most useful way to detect living-off-the-land discovery activity is to monitor for:",o:["Complete blocking of all discovery-related tools","Only outbound internet traffic","Unusual or high-volume use of system discovery tools and commands by accounts that do not normally perform them","Only known malware hashes"],c:2,x:"L'usage inhabituel ou en volume élevé d'outils de découverte par des comptes qui ne le font pas normalement est un bon indicateur.",r:"Bloquer purement tous les outils de découverte n'est pas viable."},
{d:4,e:"hard",s:"After a major incident is resolved, the most important follow-up activity is to:",o:["Assume the same attack will never happen again","Immediately reduce the security budget","Conduct a thorough lessons-learned review and implement improvements","Delete all evidence and documentation"],c:2,x:"La revue des leçons apprises suivie d'actions d'amélioration concrètes est l'activité de suivi la plus importante.",r:"Supposer que l'attaque ne se reproduira pas est dangereux."},
{d:4,e:"hard",s:"Strong relationships between the SOC and legal, compliance and communications teams primarily ensure that:",o:["Those teams are never involved in any incidents","Technical investigation is replaced by legal processes","Incidents are handled in accordance with legal, regulatory and reputational requirements","The SOC loses its authority"],c:2,x:"Ces relations assurent que les incidents sont gérés en respectant les obligations légales, réglementaires et de communication.",r:"Éviter de les impliquer expose l'organisation à des risques."},

{d:4,e:"really-hard",s:"An attacker has been using a Golden Ticket for several months. What is the MOST critical recovery action?",o:["Only reset the passwords of currently logged-in users","Only reboot all Domain Controllers","Reset the KRBTGT account password twice and carefully plan domain-wide recovery","Only delete the ticket from memory on one machine"],c:2,x:"Un Golden Ticket nécessite de réinitialiser deux fois le mot de passe du compte KRBTGT pour invalider tous les tickets existants.",r:"Un simple redémarrage des contrôleurs de domaine ne suffit pas."},
{d:4,e:"really-hard",s:"You observe LSASS access from an unusual process followed by the creation of a new service running a binary from a user-writable directory. This sequence MOST strongly indicates:",o:["Legitimate antivirus scanning","Windows Update activity","Credential dumping followed by persistence establishment","Simple software installation"],c:2,x:"L'accès à LSASS suivi de la création d'un service suspect est un enchaînement classique de dumping d'identifiants + mise en place de persistance.",r:"Ce n'est pas une activité normale de mise à jour Windows."},
{d:4,e:"really-hard",s:"Which combination is MOST effective for detecting living-off-the-land lateral movement?",o:["Only antivirus alerts","Only firewall deny logs","Detailed process creation events with command-line arguments + authentication logs + network connection data","Only DNS query volume"],c:2,x:"La combinaison télémétrie de processus + logs d'authentification + données réseau est la plus efficace contre le mouvement latéral LotL.",r:"Les alertes antivirus traditionnelles ratent souvent ces techniques."},
{d:4,e:"really-hard",s:"An attacker has obtained Domain Admin privileges. What is the MOST appropriate immediate response?",o:["Only reset the password of the Domain Admin account that was observed","Only monitor for further activity without containment","Treat the entire domain as potentially compromised and carefully plan containment and recovery","Only ask all users to change their passwords"],c:2,x:"Des droits Domain Admin imposent de considérer le domaine comme potentiellement entièrement compromis.",r:"Réinitialiser un seul compte est insuffisant."},
{d:4,e:"really-hard",s:"Which signals are MOST useful for detecting ransomware activity before mass encryption begins?",o:["Only the appearance of ransom notes","Only known ransomware file hashes after encryption has started","Mass file modifications, deletion of volume shadow copies, and unusual use of encryption-related tools or scripts","Only user reports of locked files"],c:2,x:"La détection précoce repose sur les modifications massives de fichiers et la suppression des shadow copies.",r:"Les notes de rançon et les plaintes utilisateurs arrivent trop tard."},
{d:4,e:"really-hard",s:"Which approach is MOST effective for detecting the abuse of legitimate remote administration tools by attackers?",o:["Completely blocking all remote administration tools","Only allowing remote access during business hours without further monitoring","Behavioral analysis of usage patterns, rare destinations, unusual times and anomalous parent processes","Only relying on antivirus signatures for those tools"],c:2,x:"L'analyse comportementale de l'usage des outils légitimes est plus efficace que de les bloquer complètement.",r:"Bloquer tous les outils d'administration n'est souvent pas viable opérationnellement."},
{d:4,e:"really-hard",s:"A long dwell time (attacker present for many months without detection) MOST strongly indicates a deficiency in:",o:["Password complexity requirements only","Physical security controls only","Detection capability and/or threat hunting coverage","Software update frequency only"],c:2,x:"Un long temps de présence de l'attaquant indique généralement des lacunes dans la détection ou la chasse aux menaces.",r:"Ce n'est pas principalement un problème de complexité de mot de passe."},
{d:4,e:"really-hard",s:"Which practice is MOST critical to ensure backups remain useful during a ransomware attack?",o:["Only increasing the frequency of online snapshots","Only storing backups on the same network using the same credentials","Regular restore testing of offline or immutable backups","Only relying on cloud provider default backups without testing"],c:2,x:"Des sauvegardes testées, hors ligne ou immuables sont essentielles pour résister aux ransomwares.",r:"Les snapshots en ligne sont souvent chiffrés ou supprimés par les attaquants."},
{d:4,e:"really-hard",s:"A detection rule generates a high volume of false positives. What is the BEST next step?",o:["Immediately and permanently disable the rule","Make the rule even more sensitive","Tune the rule based on environmental baselines and analyst feedback","Ignore all alerts from that rule without analysis"],c:2,x:"Le tuning des règles en fonction de l'environnement et du retour des analystes est préférable à leur désactivation pure et simple.",r:"Désactiver une règle diminue la couverture de détection."},
{d:4,e:"really-hard",s:"Which combination of capabilities is MOST effective at reducing attacker dwell time?",o:["Only strong perimeter firewalls","Only annual penetration tests","High-quality telemetry + effective detections + threat hunting + rapid response processes","Only security awareness training"],c:2,x:"Une bonne télémétrie + des détections de qualité + de la chasse aux menaces + une réponse rapide réduisent le dwell time.",r:"La sécurité périmétrique seule est insuffisante contre les menaces modernes."},

{d:4,e:"hard",s:"Which Windows event ID is commonly associated with a successful logon?",o:["4625","4648","4624","4672"],c:2,x:"L'événement 4624 enregistre une connexion réussie.",r:"4625 correspond à un échec de connexion."},
{d:4,e:"hard",s:"Which tool is most commonly used for deep packet inspection and network protocol analysis?",o:["Nmap","Metasploit","Wireshark","Nessus"],c:2,x:"Wireshark est l'outil de référence pour l'analyse approfondie de paquets et de protocoles.",r:"Nmap est un scanner de ports."},
{d:4,e:"hard",s:"What is the primary purpose of a playbook in a SOAR platform?",o:["To store raw log data long-term","To define automated or semi-automated response steps for specific incident types","To replace the need for a SIEM","To perform vulnerability scanning"],c:1,x:"Un playbook décrit les étapes de réponse automatisées ou guidées pour un type d'incident donné.",r:"Ce n'est pas un stockage de logs."},
{d:4,e:"hard",s:"Which metric measures the average time from detection of an incident to its containment or response?",o:["Mean Time to Detect (MTTD)","Mean Time Between Failures","Mean Time to Respond / Mean Time to Contain","Recovery Time Objective"],c:2,x:"MTTR / MTTC mesure le temps moyen entre la détection et la contenance ou la réponse.",r:"MTTD mesure le temps jusqu'à la détection."},
{d:4,e:"hard",s:"What is the primary purpose of maintaining chain of custody for digital evidence?",o:["To speed up the analysis process","To reduce storage costs","To maintain a verifiable record of who handled the evidence and when","To automatically analyse malware"],c:2,x:"La chaîne de custody trace la manipulation des preuves afin de garantir leur intégrité et leur recevabilité.",r:"Elle n'accélère pas l'analyse."},
{d:4,e:"really-hard",s:"Which technique is MOST effective for detecting the early stages of a ransomware attack before widespread encryption?",o:["Only detecting the encryption of files after it has started","Only relying on user reports of locked files","Monitoring for mass file access/modification, deletion of backups or shadow copies, and deployment of encryption tools","Only monitoring for known ransomware ransom notes"],c:2,x:"La détection des accès massifs aux fichiers, de la suppression des shadow copies et du déploiement d'outils de chiffrement permet une réaction avant le chiffrement généralisé.",r:"Attendre le début du chiffrement ou les notes de rançon est trop tardif."},
{d:4,e:"hard",s:"An organisation wants to detect anomalous process trees and rare parent-child process relationships. Which technology is best suited?",o:["Traditional signature-based antivirus only","Simple SIEM threshold rules only","EDR or UEBA with process behaviour analytics","Network flow data only"],c:2,x:"L'EDR et l'UEBA analysent les relations parent-enfant et les comportements de processus.",r:"Les signatures antivirus ne capturent pas les relations de processus."},
{d:4,e:"really-hard",s:"An analyst needs to examine the exact state of memory on a compromised host. Which type of acquisition is required?",o:["Disk image only","Network packet capture only","Live memory (RAM) acquisition","Registry export only"],c:2,x:"Pour analyser la mémoire volatile, une acquisition RAM live est nécessaire.",r:"Une image disque ne capture pas la mémoire volatile."},
{d:4,e:"hard",s:"Which containment strategy is generally preferred when a single workstation is confirmed compromised?",o:["Immediate full disk wipe","Shutting down the entire domain","Network isolation of the host (VLAN quarantine or firewall block)","Disabling all user accounts domain-wide"],c:2,x:"L'isolation réseau de l'hôte compromis est la contenance la plus ciblée et la moins disruptive.",r:"Un wipe immédiat détruit des preuves potentielles."},
{d:4,e:"really-hard",s:"Which order is correct for the NIST incident response lifecycle?",o:["Detection → Containment → Preparation → Recovery","Eradication → Detection → Recovery → Lessons learned","Preparation → Detection & Analysis → Containment, Eradication & Recovery → Post-incident Activity","Preparation → Recovery → Detection → Containment"],c:2,x:"Le cycle standard NIST est : Préparation → Détection/Analyse → Contenance/Éradication/Récupération → Activité post-incident.",r:"Beaucoup inversent les phases."},


// ===== DOMAIN 4 – 40 NEW QUESTIONS (Hard + Really Hard only) =====

{d:4,e:"hard",s:"Which metric measures the time between the start of an attack and its detection?",o:["Mean Time to Respond (MTTR)","Mean Time Between Failures","Dwell time / Mean Time to Detect (MTTD)","Recovery Time Objective"],c:2,x:"Le dwell time (MTTD) mesure le temps entre le début de l'attaque et sa détection.",r:"MTTR mesure le temps de réponse après détection."},
{d:4,e:"hard",s:"What should be the first containment action during active ransomware encryption?",o:["Immediately wipe all affected systems","Wait until encryption is complete","Isolate affected hosts and network segments","Shut down all domain controllers"],c:2,x:"Isoler les systèmes touchés limite la propagation et le chiffrement supplémentaire.",r:"Un wipe immédiat détruit des preuves."},
{d:4,e:"hard",s:"Which incident response phase focuses on removing malware and closing exploited vulnerabilities?",o:["Containment","Recovery","Eradication","Detection"],c:2,x:"L'éradication élimine les composants malveillants et les failles exploitées.",r:"La recovery restaure le service."},
{d:4,e:"hard",s:"Deleting or disabling Windows event logs on multiple systems is primarily an example of:",o:["Initial access","Privilege escalation","Anti-forensics / defence evasion","Data exfiltration"],c:2,x:"La suppression des journaux est une technique anti-forensique classique.",r:"Ce n'est pas de l'accès initial."},
{d:4,e:"hard",s:"Which combination is most effective for detecting LSASS credential dumping?",o:["Traditional antivirus signatures only","Network traffic analysis only","EDR monitoring of LSASS access + Credential Guard","Failed logon monitoring only"],c:2,x:"La surveillance EDR de LSASS combinée à Credential Guard est la plus efficace.",r:"Les signatures AV classiques sont souvent insuffisantes."},
{d:4,e:"hard",s:"Automatically isolating a host, disabling an account and creating a ticket is an example of:",o:["Manual analysis","Vulnerability scanning","Security orchestration and automated response","Penetration testing"],c:2,x:"C'est de l'orchestration et de l'automatisation de la réponse (SOAR).",r:"Ce n'est pas un scan de vulnérabilités."},
{d:4,e:"hard",s:"To identify the original entry point of an attacker, the most useful method is:",o:["Examining only the latest malicious process","Examining only the last logon","Building a multi-source timeline of activity","Examining only the final payload"],c:2,x:"Une timeline multi-sources permet de remonter au vecteur d'accès initial.",r:"Le payload final ne montre pas le point d'entrée."},
{d:4,e:"hard",s:"To detect attacks that move between on-premises and cloud, the most important capability is:",o:["Monitoring only on-premises Active Directory","Relying only on cloud provider alerts","Correlated visibility across identity, endpoint, network and cloud logs","Monitoring only the on-premises perimeter"],c:2,x:"La corrélation des données on-premises et cloud est essentielle pour détecter les mouvements transverses.",r:"Surveiller un seul côté laisse des angles morts."},
{d:4,e:"hard",s:"After eradication, the most important next steps are:",o:["Reduce monitoring immediately","Assume the threat is gone","Validate cleanliness, restore carefully and monitor for re-compromise","Delete all related evidence"],c:2,x:"Il faut valider que les systèmes sont propres, restaurer prudemment et surveiller les signes de retour.",r:"Réduire la surveillance trop tôt est risqué."},
{d:4,e:"hard",s:"Mapping detections to MITRE ATT&CK mainly helps to:",o:["Produce compliance reports only","Replace threat hunting","Identify detection gaps and prioritise new rules","Reduce telemetry volume"],c:2,x:"Le mapping ATT&CK permet d'identifier les trous de couverture et de prioriser les nouvelles détections.",r:"Ce n'est pas uniquement pour la conformité."},
{d:4,e:"hard",s:"The best way to detect abuse of service accounts is to monitor for:",o:["Password age only","Annual group membership reviews only","Interactive logons and unusual access patterns from service accounts","Account description field only"],c:2,x:"Les comptes de service ne devraient pas avoir de sessions interactives ni d'accès inhabituels.",r:"L'âge du mot de passe ne détecte pas l'abus."},
{d:4,e:"hard",s:"To prevent SOC team burnout during major incidents, the most important measure is:",o:["Expecting the same small team to handle everything","Avoiding documentation","Clear roles, shifts, escalation paths and surge support plans","Focusing only on technical skills"],c:2,x:"Des rôles clairs, des shifts et des plans de renfort protègent l'équipe.",r:"Une petite équipe ne peut pas tout gérer indéfiniment."},
{d:4,e:"hard",s:"The main benefit of purple team exercises is that they:",o:["Only test the red team","Only generate more alerts","Improve detection and response through collaboration between red and blue teams","Replace all other testing"],c:2,x:"Les exercices purple team améliorent la détection et la réponse de façon collaborative.",r:"Ils ne servent pas uniquement à tester l'équipe offensive."},
{d:4,e:"hard",s:"From an operational perspective, the most critical preparation against ransomware is:",o:["Phishing training only","More frequent antivirus scans only","Tested offline/immutable backups + segmentation + rapid isolation capability","Blocking macros only"],c:2,x:"Des sauvegardes testées, la segmentation et la capacité d'isolation rapide sont critiques.",r:"La formation seule est insuffisante."},
{d:4,e:"hard",s:"When a privileged account is known to be compromised, the correct approach is to:",o:["Only reset that single account","Only monitor without action","Assume wider impact, reset credentials carefully and hunt for persistence","Only notify the account owner"],c:2,x:"Une compromission de compte privilégié impose de considérer un impact potentiellement large.",r:"Réinitialiser un seul compte est souvent insuffisant."},
{d:4,e:"hard",s:"The most reliable way to reconstruct an attack timeline is to:",o:["Use a single log source","Trust attacker-controlled timestamps","Correlate multiple sources (endpoint, network, identity, etc.)","Use only the first alert timestamp"],c:2,x:"Une timeline multi-sources est la méthode la plus fiable.",r:"Une seule source est souvent incomplète."},
{d:4,e:"hard",s:"Having a defined process to engage external IR support allows a SOC to:",o:["Avoid handling incidents internally","Replace the internal SOC permanently","Bring additional expertise and capacity when needed","Use external help only for low-severity events"],c:2,x:"Un processus clair permet d'obtenir du renfort lorsque l'incident dépasse les capacités internes.",r:"Il ne vise pas à éviter de traiter les incidents."},
{d:4,e:"hard",s:"The most effective way to detect living-off-the-land discovery activity is to monitor for:",o:["Blocking all discovery tools","Outbound internet traffic only","Unusual use of discovery commands by accounts that do not normally use them","Known malware hashes only"],c:2,x:"L'usage inhabituel d'outils de découverte par certains comptes est un bon signal.",r:"Bloquer purement ces outils n'est pas réaliste."},
{d:4,e:"hard",s:"After resolving a major incident, the most important follow-up is to:",o:["Assume it will never happen again","Reduce the security budget","Conduct a lessons-learned review and implement improvements","Delete all evidence"],c:2,x:"La revue des leçons apprises et la mise en œuvre d'améliorations sont essentielles.",r:"Supposer que l'attaque ne se reproduira pas est dangereux."},
{d:4,e:"hard",s:"Strong collaboration between the SOC and legal/compliance teams mainly ensures:",o:["Those teams are never involved","Technical work is replaced by legal processes","Incidents are handled according to legal and regulatory requirements","The SOC loses authority"],c:2,x:"Cette collaboration garantit le respect des obligations légales et réglementaires.",r:"Les exclure expose l'organisation."},

{d:4,e:"really-hard",s:"An attacker has been using a Golden Ticket for months. What is the most critical recovery step?",o:["Reset only currently logged-on user passwords","Reboot all domain controllers","Reset the KRBTGT password twice and plan domain recovery carefully","Delete the ticket from one machine’s memory"],c:2,x:"Il faut réinitialiser deux fois le mot de passe KRBTGT pour invalider les Golden Tickets.",r:"Un simple redémarrage des DC est insuffisant."},
{d:4,e:"really-hard",s:"LSASS access by an unusual process followed by a new service running from a user-writable path most strongly indicates:",o:["Antivirus activity","Windows Update","Credential dumping followed by persistence","Normal software installation"],c:2,x:"Cet enchaînement est typique d'un dumping d'identifiants suivi de mise en place de persistance.",r:"Ce n'est pas une activité de mise à jour Windows."},
{d:4,e:"really-hard",s:"Which data combination is most effective for detecting living-off-the-land lateral movement?",o:["Antivirus alerts only","Firewall deny logs only","Process creation with command lines + authentication logs + network connections","DNS query volume only"],c:2,x:"La combinaison processus + authentification + réseau est la plus efficace contre le mouvement latéral LotL.",r:"Les alertes AV classiques ratent souvent ces techniques."},
{d:4,e:"really-hard",s:"When an attacker has obtained Domain Admin rights, the most appropriate immediate response is to:",o:["Reset only the observed Domain Admin password","Monitor without containment","Treat the domain as potentially fully compromised and plan recovery carefully","Ask all users to change passwords"],c:2,x:"Des droits Domain Admin imposent de considérer le domaine comme potentiellement compromis dans son ensemble.",r:"Réinitialiser un seul compte est insuffisant."},
{d:4,e:"really-hard",s:"Which signals are most useful for detecting ransomware before mass encryption starts?",o:["Ransom notes only","Known ransomware hashes after encryption","Mass file modifications, shadow copy deletion and unusual encryption tool usage","User reports of locked files only"],c:2,x:"Les modifications massives de fichiers et la suppression des shadow copies sont des signaux précoces.",r:"Les notes de rançon arrivent trop tard."},
{d:4,e:"really-hard",s:"Which method is most effective for detecting abuse of legitimate remote administration tools?",o:["Blocking all remote admin tools","Allowing them only during business hours without monitoring","Behavioral analysis of usage patterns, destinations and timing","Relying only on antivirus signatures"],c:2,x:"L'analyse comportementale de l'usage des outils légitimes est plus efficace que le blocage total.",r:"Bloquer tous ces outils n'est souvent pas possible."},
{d:4,e:"really-hard",s:"A very long attacker dwell time most strongly suggests weakness in:",o:["Password complexity only","Physical security only","Detection and/or threat hunting capabilities","Patch frequency only"],c:2,x:"Un long temps de présence indique des lacunes dans la détection ou la chasse aux menaces.",r:"Ce n'est pas principalement un problème de complexité de mot de passe."},
{d:4,e:"really-hard",s:"Which practice is most critical to keep backups effective against ransomware?",o:["More frequent online snapshots only","Storing backups on the same network with the same credentials","Regular testing of offline or immutable backups","Relying on default cloud backups without testing"],c:2,x:"Des sauvegardes testées, hors ligne ou immuables sont essentielles.",r:"Les snapshots en ligne sont souvent ciblés par les ransomwares."},
{d:4,e:"really-hard",s:"When a detection rule produces too many false positives, the best action is to:",o:["Disable the rule permanently","Make the rule more sensitive","Tune the rule using environmental baselines and analyst feedback","Ignore all its alerts"],c:2,x:"Le tuning de la règle est préférable à sa désactivation pure et simple.",r:"Désactiver une règle réduit la couverture de détection."},
{d:4,e:"really-hard",s:"Which combination is most effective at reducing attacker dwell time?",o:["Strong perimeter firewalls only","Annual penetration tests only","High-quality telemetry + good detections + threat hunting + rapid response","Security awareness training only"],c:2,x:"Télémétrie + détections + chasse + réponse rapide réduisent le dwell time.",r:"Le périmètre seul est insuffisant."},

{d:4,e:"hard",s:"Which Windows event ID typically records a successful account logon?",o:["4625","4648","4624","4672"],c:2,x:"L'événement 4624 correspond à une connexion réussie.",r:"4625 correspond à un échec."},
{d:4,e:"hard",s:"Which tool is most commonly used for detailed packet capture and protocol analysis?",o:["Nmap","Metasploit","Wireshark","Nessus"],c:2,x:"Wireshark est l'outil standard pour l'analyse de paquets.",r:"Nmap est un scanner de ports."},
{d:4,e:"hard",s:"What is the main purpose of a SOAR playbook?",o:["Long-term log storage","Defining automated or guided response steps for specific incident types","Replacing the SIEM","Vulnerability scanning"],c:1,x:"Un playbook décrit les étapes de réponse pour un type d'incident donné.",r:"Ce n'est pas un stockage de logs."},
{d:4,e:"hard",s:"Which metric measures the average time from detection to containment or response?",o:["Mean Time to Detect","Mean Time Between Failures","Mean Time to Respond / Mean Time to Contain","Recovery Time Objective"],c:2,x:"MTTR/MTTC mesure le temps entre détection et réponse/contenance.",r:"MTTD mesure le temps jusqu'à la détection."},
{d:4,e:"hard",s:"What is the primary purpose of chain of custody?",o:["Speeding up analysis","Reducing storage costs","Maintaining a verifiable record of evidence handling","Automatic malware analysis"],c:2,x:"La chaîne de custody trace qui a manipulé les preuves et quand, pour garantir leur intégrité.",r:"Elle n'accélère pas l'analyse."},
{d:4,e:"really-hard",s:"Which technique is most effective for detecting ransomware before widespread encryption occurs?",o:["Detecting encryption after it starts","Relying on user reports of locked files","Monitoring mass file changes, shadow copy deletion and encryption tool usage","Waiting for ransom notes"],c:2,x:"La surveillance des modifications massives de fichiers et de la suppression des shadow copies permet une détection précoce.",r:"Attendre le chiffrement ou les notes de rançon est trop tardif."},
{d:4,e:"hard",s:"Which technology is best suited to detect unusual parent-child process relationships?",o:["Signature-based antivirus only","Simple SIEM thresholds only","EDR or UEBA with process behaviour analytics","Network flow data only"],c:2,x:"L'EDR et l'UEBA analysent les relations et comportements de processus.",r:"Les signatures AV ne voient pas ces relations."},
{d:4,e:"really-hard",s:"To examine the exact contents of memory on a compromised system, which acquisition is required?",o:["Disk image only","Packet capture only","Live memory (RAM) acquisition","Registry export only"],c:2,x:"L'analyse de la mémoire volatile nécessite une acquisition RAM live.",r:"Une image disque ne capture pas la RAM."},
{d:4,e:"hard",s:"When a single workstation is confirmed compromised, the preferred containment action is usually:",o:["Immediate full disk wipe","Shutting down the entire domain","Network isolation of the host","Disabling all domain accounts"],c:2,x:"L'isolation réseau de l'hôte est la contenance la plus précise et la moins disruptive.",r:"Un wipe immédiat détruit des preuves."},
{d:4,e:"really-hard",s:"What is the correct order of the NIST incident response lifecycle?",o:["Detection → Containment → Preparation → Recovery","Eradication → Detection → Recovery → Lessons learned","Preparation → Detection & Analysis → Containment/Eradication/Recovery → Post-incident Activity","Preparation → Recovery → Detection → Containment"],c:2,x:"Le cycle NIST est : Préparation → Détection & Analyse → Contenance/Éradication/Récupération → Activité post-incident.",r:"Les phases sont souvent inversées par erreur."},

// ====================== DOMAIN 5 ======================
{d:5,e:"medium",s:"What does the acronym CIA stand for in security?",o:["Central Intelligence Agency","Control, Identify, Authenticate","Confidentiality, Integrity, Availability","Compliance, Integrity, Audit"],c:2,x:"CIA = Confidentialité, Intégrité, Disponibilité.",r:"Ce n'est pas l'agence de renseignement."},
{d:5,e:"medium",s:"Which of the following is a common risk treatment option?",o:["Only Accept","Only Ignore","Mitigate, Transfer, Accept, or Avoid","Only Increase the risk"],c:2,x:"Les options classiques sont : mitiger, transférer, accepter ou éviter.",r:"Ignorer n'est pas une option valable."},
{d:5,e:"medium",s:"What is the primary purpose of a Business Impact Analysis (BIA)?",o:["List all technical vulnerabilities","Define the organisation’s risk appetite","Identify critical business functions and the impact of their disruption","Create firewall rules"],c:2,x:"La BIA identifie les fonctions critiques et l'impact d'une interruption.",r:"Ce n'est pas un scan de vulnérabilités."},

{d:5,e:"hard",s:"Which document defines the organisation’s acceptable level of residual risk?",o:["Risk register","Business impact analysis","Risk appetite statement","Incident response plan"],c:2,x:"Le risk appetite définit le niveau de risque résiduel acceptable.",r:"Le risk register liste les risques identifiés."},
{d:5,e:"hard",s:"Purchasing cyber insurance is an example of:",o:["Risk avoidance","Risk mitigation","Risk transference","Risk acceptance"],c:2,x:"L'assurance est une forme de transfert de risque.",r:"La mitigation réduit le risque par des contrôles."},
{d:5,e:"hard",s:"When a third-party processor has a breach involving personal data, which agreement is MOST important for notification duties?",o:["Simple NDA","Uptime SLA only","Data Processing Agreement (DPA)","Memorandum of understanding"],c:2,x:"Le DPA définit les obligations de notification et de responsabilité en cas de violation de données.",r:"L'NDA protège la confidentialité commerciale."},
{d:5,e:"hard",s:"Residual risk is BEST defined as:",o:["The risk before any controls are applied","Always zero if any controls exist","The risk that remains after controls have been applied","Only relevant to financial risks"],c:2,x:"Le risque résiduel est celui qui reste après l'application des contrôles.",r:"Le risque inhérent est celui avant les contrôles."},
{d:5,e:"hard",s:"Which statement about compliance and security is MOST accurate?",o:["Compliance automatically equals full security","Security and compliance are completely unrelated","Compliance is necessary but not sufficient for good security","Compliance only matters for public companies"],c:2,x:"La conformité est nécessaire mais pas suffisante ; une bonne sécurité va souvent au-delà.",r:"Être conforme ne signifie pas automatiquement être bien sécurisé."},
{d:5,e:"hard",s:"Regular access reviews of privileged accounts are primarily performed to:",o:["Only satisfy auditors with no security value","Increase the number of privileged accounts","Ensure access remains appropriate and detect privilege creep","Replace the need for authentication"],c:2,x:"Les revues d'accès permettent de maintenir le moindre privilège et de détecter les comptes excessifs ou orphelins.",r:"Ce n'est pas uniquement pour satisfaire les auditeurs."},

{d:5,e:"really-hard",s:"A company accepts a high residual risk without documenting the decision, the risk owner, or monitoring requirements. This is primarily a failure of:",o:["Technical control implementation","Vulnerability scanning frequency","Risk acceptance process and accountability","Incident response speed"],c:2,x:"Une acceptation de risque non documentée et sans propriétaire clair est un échec de gouvernance.",r:"Ce n'est pas principalement un problème technique."},
{d:5,e:"really-hard",s:"Which situation BEST demonstrates a failure of third-party risk management?",o:["A supplier is assessed every year and has strong contractual requirements","A supplier is required to provide SOC 2 reports annually","A critical supplier processes sensitive data but has never been assessed and has no security clauses","A supplier is only used for non-sensitive marketing materials"],c:2,x:"Ne jamais évaluer un fournisseur critique qui traite des données sensibles est un échec majeur de gestion des risques tiers.",r:"Des évaluations régulières sont une bonne pratique."},
{d:5,e:"really-hard",s:"Which framework is MOST widely used in the United States for organisational cybersecurity risk management?",o:["ISO 27001 only","COBIT only","NIST Cybersecurity Framework / NIST RMF","ITIL only"],c:2,x:"Le NIST CSF et le RMF sont les plus utilisés aux États-Unis pour la gestion du risque cyber.",r:"ISO 27001 est important internationalement mais NIST domine aux US."},

// ===== DOMAIN 5 – 40 NEW QUESTIONS (Hard + Really Hard only) =====

{d:5,e:"hard",s:"Which document formally defines how much residual risk an organisation is willing to accept?",o:["Risk register","Business impact analysis","Risk appetite statement","Disaster recovery plan"],c:2,x:"Le risk appetite définit le niveau de risque résiduel acceptable par la direction.",r:"Le risk register liste les risques identifiés."},
{d:5,e:"hard",s:"When a third-party processor suffers a breach involving personal data, which agreement is most critical for determining notification duties and liability?",o:["Simple non-disclosure agreement (NDA)","Service level agreement for uptime only","Data Processing Agreement (DPA)","Memorandum of understanding"],c:2,x:"Le DPA (ou clauses équivalentes) définit les obligations de notification et de responsabilité en cas de violation de données.",r:"L'NDA protège principalement la confidentialité commerciale."},
{d:5,e:"hard",s:"Purchasing cyber insurance is an example of which risk treatment strategy?",o:["Risk avoidance","Risk mitigation","Risk transference","Risk acceptance"],c:2,x:"L'achat d'assurance est une forme de transfert de risque.",r:"La mitigation réduit le risque par des contrôles."},
{d:5,e:"hard",s:"What is the primary purpose of a Business Impact Analysis (BIA)?",o:["List all technical vulnerabilities in the environment","Define the organisation’s risk appetite","Identify critical business functions and the impact of their disruption","Create detailed incident response playbooks"],c:2,x:"La BIA identifie les fonctions critiques et quantifie l'impact d'une interruption (RTO, RPO, etc.).",r:"Ce n'est pas un inventaire de vulnérabilités."},
{d:5,e:"hard",s:"Risk assessments should be:",o:["Performed only once when the organisation is founded","Done only for compliance with no operational value","Repeated periodically and when significant changes occur in the environment or threat landscape","Used to replace all security controls"],c:2,x:"Les évaluations de risque doivent être périodiques et mises à jour lors de changements significatifs.",r:"Une évaluation unique devient rapidement obsolète."},
{d:5,e:"hard",s:"When an organisation decides not to implement a control because its cost exceeds the expected benefit, this is an example of:",o:["Risk avoidance","Risk mitigation","Risk transference","Informed risk acceptance"],c:3,x:"Lorsque le coût du contrôle dépasse le bénéfice attendu, l'organisation peut accepter le risque de façon informée.",r:"Ce n'est pas de l'évitement du risque."},
{d:5,e:"hard",s:"Which framework is most widely used in the United States for managing cybersecurity risk at an organisational level?",o:["ISO 27001 only","COBIT only","NIST Cybersecurity Framework and/or NIST Risk Management Framework","ITIL only"],c:2,x:"Le NIST CSF et le RMF sont les références les plus utilisées aux États-Unis pour la gestion du risque cyber.",r:"ISO 27001 est très important internationalement, mais NIST domine dans le contexte américain."},
{d:5,e:"hard",s:"A good security metric for senior leadership should primarily be:",o:["Highly technical and detailed","Focused only on the number of blocked attacks","Expressed in business-relevant terms and useful for risk decisions","Never changing over time"],c:2,x:"Les métriques destinées au leadership doivent être exprimées en termes business et aider à la prise de décision.",r:"Des métriques purement techniques sont souvent peu actionnables à ce niveau."},
{d:5,e:"hard",s:"When onboarding a critical supplier that will process sensitive data, the most important activities are:",o:["Only choosing the cheapest supplier","Only relying on the supplier’s marketing claims","Security due diligence, contractual security requirements, and ongoing monitoring rights","Only signing a basic NDA"],c:2,x:"La due diligence, les exigences contractuelles de sécurité et les droits de monitoring sont essentiels.",r:"Se fier uniquement au marketing du fournisseur est insuffisant."},
{d:5,e:"hard",s:"A legal requirement to notify personal data breaches within a fixed timeframe (for example 72 hours) is an example of:",o:["A purely optional technical best practice","An industry recommendation with no legal weight","A regulatory compliance obligation","A contractual term that can be ignored"],c:2,x:"Les délais de notification de violation de données sont des obligations légales/réglementaires (ex. RGPD).",r:"Ce n'est pas une simple recommandation optionnelle."},
{d:5,e:"hard",s:"Residual risk is best defined as:",o:["The risk before any controls are applied","Always zero if any controls exist","The risk that remains after controls have been applied","Only relevant to financial risks"],c:2,x:"Le risque résiduel est celui qui demeure après l'application des contrôles.",r:"Le risque inhérent est celui avant les contrôles."},
{d:5,e:"hard",s:"From a governance perspective, the primary purpose of a security awareness and training programme is to:",o:["Only satisfy a compliance checkbox with no real impact","Replace the need for technical controls","Reduce human-related risk and demonstrate due diligence","Completely eliminate all insider threat risk"],c:2,x:"Un programme de sensibilisation réduit le risque humain et démontre la diligence de l'organisation.",r:"Il ne remplace pas les contrôles techniques."},
{d:5,e:"hard",s:"The high-level document that defines an organisation’s security objectives and principles is typically the:",o:["Server hardening procedure","Risk register entry","Information security policy","Ransomware response playbook"],c:2,x:"La politique de sécurité de l'information définit les objectifs et principes de haut niveau.",r:"Les procédures techniques détaillées sont des documents de niveau inférieur."},
{d:5,e:"hard",s:"When a critical control has not been operating effectively for several months, the most important governance action is to:",o:["Ignore it if no known breach occurred","Only fix the control without any risk assessment","Assess the resulting risk exposure, notify appropriate stakeholders, and implement corrective actions","Only document it without taking further action"],c:2,x:"Il faut évaluer l'exposition au risque résultante, informer les parties prenantes et mettre en place des actions correctives.",r:"Ignorer le problème expose l'organisation."},
{d:5,e:"hard",s:"The principle that personal data should not be kept longer than necessary for the stated purpose is known as:",o:["Maximum data retention for potential future use","Collecting as much data as possible by default","Storage limitation / data minimisation","Sharing data freely with all third parties"],c:2,x:"Les principes de minimisation et de limitation de la conservation des données sont centraux dans les réglementations de protection des données.",r:"Conserver les données indéfiniment va à l'encontre de ces principes."},
{d:5,e:"hard",s:"Regular access reviews of privileged accounts are primarily performed to:",o:["Only satisfy auditors with no real security benefit","Increase the number of privileged accounts","Ensure access remains appropriate and detect privilege creep or orphaned accounts","Replace the need for authentication"],c:2,x:"Les revues d'accès permettent de maintenir le moindre privilège et de détecter les comptes excessifs ou orphelins.",r:"Ce n'est pas uniquement pour satisfaire les auditeurs."},
{d:5,e:"hard",s:"Which statement about compliance and security is most accurate?",o:["Achieving compliance automatically means the organisation is fully secure","Security and compliance are completely unrelated","Compliance is necessary but not sufficient for good security; security often requires going beyond minimum requirements","Compliance is only relevant for public companies"],c:2,x:"La conformité est nécessaire mais pas suffisante ; une bonne sécurité va souvent au-delà des exigences minimales de conformité.",r:"Être conforme ne signifie pas automatiquement être bien sécurisé."},
{d:5,e:"hard",s:"When presenting cyber risk to a board of directors, the most appropriate approach is to:",o:["Only show the number of blocked malware events","Only list all technical vulnerabilities without context","Present residual risk in business terms, linked to critical assets and processes, with clear treatment decisions","Only provide raw log volumes"],c:2,x:"Le conseil d'administration a besoin d'une vision du risque résiduel exprimée en termes business.",r:"Les compteurs techniques bruts ne sont pas actionnables à ce niveau."},
{d:5,e:"hard",s:"When an organisation formally accepts a significant residual risk, it should also:",o:["Keep the acceptance decision informal and undocumented","Only inform the technical team","Document the decision, the rationale, the risk owner, and any monitoring conditions","Automatically transfer the risk to a third party without analysis"],c:2,x:"L'acceptation d'un risque significatif doit être documentée, avec un propriétaire clair et des conditions éventuelles de monitoring.",r:"Une acceptation informelle est dangereuse d'un point de vue gouvernance."},
{d:5,e:"hard",s:"From a governance and risk perspective, continuous monitoring primarily serves to:",o:["Only generate more alerts for the SOC","Replace periodic risk assessments completely","Provide ongoing assurance that controls remain effective and that risk stays within acceptable levels","Eliminate all need for human oversight"],c:2,x:"La surveillance continue fournit une assurance permanente sur l'efficacité des contrôles et le niveau de risque.",r:"Elle ne remplace pas totalement les évaluations de risque périodiques."},

{d:5,e:"really-hard",s:"A company accepts a high residual risk without documenting the decision, the risk owner, or any monitoring requirements. From a governance perspective, this is primarily a failure of:",o:["Technical control implementation","Vulnerability scanning frequency","Risk acceptance process and accountability","Incident response speed"],c:2,x:"Une acceptation de risque non documentée et sans propriétaire clair est un échec de gouvernance.",r:"Ce n'est pas principalement un problème technique."},
{d:5,e:"really-hard",s:"Which situation best demonstrates a failure of third-party risk management?",o:["A supplier is assessed every year and has strong contractual security requirements","A supplier is required to provide SOC 2 reports annually","A critical supplier processes sensitive data but has never been assessed and has no security clauses in the contract","A supplier is only used for non-sensitive marketing materials"],c:2,x:"Ne jamais évaluer un fournisseur critique qui traite des données sensibles est un échec majeur de gestion des risques tiers.",r:"Des évaluations régulières et des clauses contractuelles sont de bonnes pratiques."},
{d:5,e:"really-hard",s:"Which framework is most commonly used in the United States for organisational cybersecurity risk management?",o:["ISO 27001 only","COBIT only","NIST Cybersecurity Framework (CSF) and/or NIST Risk Management Framework (RMF)","ITIL only"],c:2,x:"Le NIST CSF et le RMF sont les plus utilisés aux États-Unis pour la gestion du risque cyber au niveau organisationnel.",r:"ISO 27001 est important internationalement, mais NIST domine dans le contexte américain."},
{d:5,e:"really-hard",s:"Which activity is most essential when a new regulation affecting the organisation is published?",o:["Ignore it until an auditor asks about it","Only inform the legal department without further action","Assess the impact, identify gaps, and plan necessary changes to policies, processes and controls","Immediately buy a new tool without analysis"],c:2,x:"Il faut évaluer l'impact de la nouvelle réglementation, identifier les écarts et planifier les changements nécessaires.",r:"Ignorer la réglementation expose l'organisation."},
{d:5,e:"really-hard",s:"The primary reason for maintaining an accurate inventory of systems and data is to:",o:["Increase administrative overhead only","Replace the need for vulnerability management","Know what needs protection and support risk assessment and prioritisation","Eliminate the need for network scanning"],c:2,x:"Un inventaire précis permet de savoir ce qu'il faut protéger et de prioriser les efforts de sécurité.",r:"Il ne remplace pas la gestion des vulnérabilités."},
{d:5,e:"really-hard",s:"Which statement best describes the relationship between policies, standards and procedures?",o:["They are interchangeable terms with the same meaning","Procedures are higher level than policies","Policies set high-level direction, standards define mandatory requirements, procedures give step-by-step instructions","Standards are always optional while policies are mandatory"],c:2,x:"Les politiques donnent la direction, les standards fixent les exigences obligatoires, les procédures décrivent les étapes détaillées.",r:"Ces termes ne sont pas interchangeables."},
{d:5,e:"really-hard",s:"When a significant security incident occurs, governance requires that:",o:["Only the technical team knows about it","No records are kept to avoid liability","Appropriate stakeholders are informed according to defined escalation and notification processes","Public communication is avoided at all costs"],c:2,x:"Les processus d'escalade et de notification doivent être suivis pour informer les bonnes parties prenantes.",r:"Cacher l'incident n'est pas une bonne pratique de gouvernance."},
{d:5,e:"really-hard",s:"The most important characteristic of a risk owner is that they:",o:["Are always a technical specialist","Are always a member of the SOC","Have the authority and accountability to make decisions about the risk","Have no decision-making power"],c:2,x:"Le propriétaire du risque doit avoir l'autorité et la responsabilité de décider du traitement du risque.",r:"Ce n'est pas forcément un spécialiste technique."},
{d:5,e:"really-hard",s:"Which activity best demonstrates due diligence in third-party risk management?",o:["Only trusting the third party’s self-attestation","Only checking the third party’s website","Performing security assessments, defining contractual security requirements, and monitoring ongoing compliance","Only signing a contract without any security clauses"],c:2,x:"Évaluations de sécurité, exigences contractuelles et monitoring continu démontrent la due diligence.",r:"Se fier uniquement à l'auto-déclaration du fournisseur est insuffisant."},
{d:5,e:"really-hard",s:"A control that is required by law or regulation is best described as:",o:["An optional best practice","A purely technical recommendation","A compliance / regulatory requirement","A contractual preference only"],c:2,x:"Une exigence légale ou réglementaire est obligatoire.",r:"Ce n'est pas une simple bonne pratique optionnelle."},

{d:5,e:"hard",s:"The primary purpose of a security governance framework is to:",o:["Replace all technical security controls","Eliminate the need for risk assessment","Ensure security activities are aligned with business objectives and risk appetite","Focus only on compliance checklists"],c:2,x:"La gouvernance de la sécurité aligne les activités de sécurité sur les objectifs business et l'appétit pour le risque.",r:"Elle ne remplace pas les contrôles techniques."},
{d:5,e:"hard",s:"When residual risk is accepted, the organisation should also:",o:["Never look at the risk again","Automatically transfer it to a third party","Define any required monitoring and review the acceptance periodically","Ignore any related incidents"],c:2,x:"L'acceptation d'un risque doit s'accompagner de monitoring et de revues périodiques.",r:"Ignorer le risque après l'avoir accepté est dangereux."},
{d:5,e:"hard",s:"Which of the following is the best example of a governance-level security metric?",o:["Number of raw log events collected per day","Number of firewall rules","Percentage of critical systems covered by tested backups and the residual risk trend","Number of antivirus signatures"],c:2,x:"Une métrique de gouvernance lie la couverture de contrôles critiques à l'évolution du risque résiduel.",r:"Le volume brut de logs n'est pas une métrique de gouvernance."},
{d:5,e:"hard",s:"Which concept requires that the same person should not be able to both initiate and approve a critical transaction?",o:["Least privilege","Need to know","Separation of duties","Defense in depth"],c:2,x:"La séparation des tâches empêche qu'une seule personne contrôle l'ensemble d'un processus critique.",r:"Le moindre privilège limite les droits mais ne force pas la dualité des rôles."},
{d:5,e:"really-hard",s:"Which of the following best illustrates a mature approach to risk treatment decisions?",o:["Always implementing every possible control regardless of cost","Documenting the decision, assigning a risk owner, and defining monitoring for accepted residual risks","Keeping all risk acceptance decisions informal","Transferring every risk to insurance without analysis"],c:1,x:"Une approche mature documente les décisions, désigne un propriétaire et définit le suivi des risques acceptés.",r:"Implémenter tous les contrôles possibles sans regarder le coût n'est pas réaliste."},
{d:5,e:"hard",s:"What is the main purpose of maintaining a risk register?",o:["To replace the need for security controls","To list identified risks, their owners, treatment decisions and status","To increase administrative work only","To eliminate residual risk completely"],c:1,x:"Le risk register permet de suivre les risques identifiés, leurs propriétaires, les décisions de traitement et leur statut.",r:"Il ne remplace pas les contrôles de sécurité."},
{d:5,e:"really-hard",s:"In the context of data protection regulations, what does the principle of accountability require?",o:["That organisations only collect data for marketing purposes","That organisations can demonstrate compliance with data protection principles and obligations","That data is never shared with any third party","That all data is deleted after 30 days"],c:1,x:"Le principe de responsabilité (accountability) exige que l'organisation puisse démontrer sa conformité aux principes de protection des données.",r:"Il ne se limite pas à une durée de conservation fixe."},
{d:5,e:"hard",s:"Which of the following is a key output of a Business Impact Analysis?",o:["A list of all open ports on servers","Recovery Time Objectives (RTO) and Recovery Point Objectives (RPO) for critical processes","A complete inventory of firewall rules","A phishing simulation report"],c:1,x:"La BIA produit notamment les RTO et RPO pour les processus critiques.",r:"Ce n'est pas un scan de ports."},
{d:5,e:"really-hard",s:"Which statement best describes the correct relationship between inherent risk and residual risk?",o:["Residual risk is always higher than inherent risk","Inherent risk is the risk that remains after controls, residual risk is the risk before controls","Inherent risk is the risk before controls are applied; residual risk is the risk that remains after controls","They are two terms for the same concept"],c:2,x:"Le risque inhérent existe avant les contrôles ; le risque résiduel reste après l'application des contrôles.",r:"Les deux termes ne sont pas interchangeables."},
{d:5,e:"hard",s:"What is the primary purpose of assigning a risk owner?",o:["To increase the number of meetings","To have someone accountable for decisions about the treatment and monitoring of that risk","To replace the need for a risk register","To eliminate the risk automatically"],c:1,x:"Le propriétaire du risque est responsable des décisions de traitement et du suivi de ce risque.",r:"Il ne supprime pas automatiquement le risque."},

// ===== DOMAIN 5 – 40 NEW QUESTIONS (Hard + Really Hard only) =====

{d:5,e:"hard",s:"Which document defines the amount of residual risk an organisation is prepared to accept?",o:["Risk register","Business impact analysis","Risk appetite statement","Incident response plan"],c:2,x:"Le risk appetite définit le niveau de risque résiduel que l'organisation accepte.",r:"Le risk register liste les risques identifiés."},
{d:5,e:"hard",s:"When a third-party processor has a personal data breach, which agreement is most important for notification obligations?",o:["Non-disclosure agreement","Uptime SLA","Data Processing Agreement (DPA)","Memorandum of understanding"],c:2,x:"Le DPA définit les obligations de notification et de responsabilité en cas de violation de données.",r:"L'NDA protège surtout la confidentialité commerciale."},
{d:5,e:"hard",s:"Buying cyber insurance is an example of which risk treatment option?",o:["Risk avoidance","Risk mitigation","Risk transference","Risk acceptance"],c:2,x:"L'assurance est une forme de transfert de risque.",r:"La mitigation réduit le risque par des contrôles."},
{d:5,e:"hard",s:"What is the main purpose of a Business Impact Analysis?",o:["List technical vulnerabilities","Define risk appetite","Identify critical business functions and the impact of their disruption","Write incident response playbooks"],c:2,x:"La BIA identifie les fonctions critiques et l'impact d'une interruption (RTO, RPO, etc.).",r:"Ce n'est pas un scan de vulnérabilités."},
{d:5,e:"hard",s:"How often should risk assessments be performed?",o:["Only once when the organisation is created","Only for compliance purposes","Periodically and when significant changes occur","Never, if controls are in place"],c:2,x:"Les évaluations de risque doivent être périodiques et mises à jour lors de changements importants.",r:"Une évaluation unique devient vite obsolète."},
{d:5,e:"hard",s:"Choosing not to implement a control because its cost exceeds the expected benefit is an example of:",o:["Risk avoidance","Risk mitigation","Risk transference","Informed risk acceptance"],c:3,x:"Lorsque le coût du contrôle dépasse le bénéfice, l'organisation peut accepter le risque de façon informée.",r:"Ce n'est pas de l'évitement."},
{d:5,e:"hard",s:"Which framework is most commonly used in the United States for organisational cybersecurity risk management?",o:["ISO 27001 only","COBIT only","NIST CSF and/or NIST RMF","ITIL only"],c:2,x:"Le NIST CSF et le RMF sont les plus utilisés aux États-Unis pour la gestion du risque cyber.",r:"ISO 27001 est important internationalement mais NIST domine aux US."},
{d:5,e:"hard",s:"A useful security metric for senior leadership should be:",o:["Highly technical","Focused only on blocked attacks","Expressed in business terms and helpful for decision-making","Unchanging over time"],c:2,x:"Les métriques pour la direction doivent être exprimées en langage business et aider à la décision.",r:"Des métriques purement techniques sont peu actionnables à ce niveau."},
{d:5,e:"hard",s:"When onboarding a critical supplier that will handle sensitive data, the most important actions are:",o:["Choose the cheapest supplier","Rely on marketing claims","Perform security due diligence, define contractual requirements and retain monitoring rights","Sign only a basic NDA"],c:2,x:"Due diligence, clauses de sécurité et droits de monitoring sont essentiels.",r:"Se fier au marketing est insuffisant."},
{d:5,e:"hard",s:"A legal obligation to notify a personal data breach within a fixed time is an example of:",o:["Optional best practice","Industry recommendation only","Regulatory compliance requirement","Ignorable contractual term"],c:2,x:"Les délais de notification de breach sont des obligations réglementaires.",r:"Ce n'est pas une simple recommandation optionnelle."},
{d:5,e:"hard",s:"Residual risk is best defined as:",o:["Risk before any controls","Always zero once controls exist","Risk remaining after controls are applied","Only financial risk"],c:2,x:"Le risque résiduel est celui qui reste après l'application des contrôles.",r:"Le risque inhérent est celui avant les contrôles."},
{d:5,e:"hard",s:"From a governance perspective, the main purpose of security awareness training is to:",o:["Tick a compliance box only","Replace technical controls","Reduce human-related risk and show due diligence","Eliminate all insider threat"],c:2,x:"La sensibilisation réduit le risque humain et démontre la diligence de l'organisation.",r:"Elle ne remplace pas les contrôles techniques."},
{d:5,e:"hard",s:"The high-level document that sets an organisation’s security direction and principles is the:",o:["Hardening procedure","Risk register entry","Information security policy","Incident playbook"],c:2,x:"La politique de sécurité de l'information définit les objectifs et principes de haut niveau.",r:"Les procédures techniques sont de niveau inférieur."},
{d:5,e:"hard",s:"When a critical control has failed for several months, the most important governance step is to:",o:["Ignore it if no breach was seen","Fix it without assessing risk","Assess the risk exposure, inform stakeholders and take corrective action","Only document it"],c:2,x:"Il faut évaluer le risque résultant, informer les parties prenantes et corriger.",r:"Ignorer le problème est dangereux."},
{d:5,e:"hard",s:"The principle that personal data must not be kept longer than necessary is called:",o:["Maximum retention","Collect everything by default","Storage limitation / data minimisation","Share freely with third parties"],c:2,x:"La limitation de conservation et la minimisation des données sont des principes clés de protection des données.",r:"Conserver indéfiniment va contre ces principes."},
{d:5,e:"hard",s:"Regular access reviews of privileged accounts are mainly performed to:",o:["Satisfy auditors only","Increase privileged accounts","Ensure access is still appropriate and detect privilege creep","Replace authentication"],c:2,x:"Les revues d'accès maintiennent le moindre privilège et détectent les comptes excessifs ou orphelins.",r:"Ce n'est pas uniquement pour les auditeurs."},
{d:5,e:"hard",s:"Which statement about compliance and security is most accurate?",o:["Compliance equals complete security","Security and compliance are unrelated","Compliance is necessary but not sufficient; good security often goes beyond minimum requirements","Compliance only matters for public companies"],c:2,x:"La conformité est nécessaire mais pas suffisante ; la sécurité va souvent plus loin.",r:"Être conforme ne signifie pas être pleinement sécurisé."},
{d:5,e:"hard",s:"When presenting cyber risk to the board, the best approach is to:",o:["Show only blocked malware counts","List technical vulnerabilities without context","Present residual risk in business terms linked to critical assets and processes","Show raw log volumes"],c:2,x:"Le conseil a besoin d'une vision du risque résiduel en termes business.",r:"Les compteurs techniques bruts ne sont pas actionnables à ce niveau."},
{d:5,e:"hard",s:"When accepting a significant residual risk, the organisation should:",o:["Keep the decision informal","Tell only the technical team","Document the decision, rationale, risk owner and monitoring requirements","Automatically transfer it without analysis"],c:2,x:"L'acceptation d'un risque important doit être documentée avec un propriétaire et des conditions de suivi.",r:"Une acceptation informelle est dangereuse."},
{d:5,e:"hard",s:"Continuous monitoring from a governance perspective mainly provides:",o:["More SOC alerts only","Complete replacement of risk assessments","Ongoing assurance that controls remain effective and risk stays acceptable","Elimination of human oversight"],c:2,x:"La surveillance continue donne une assurance permanente sur les contrôles et le niveau de risque.",r:"Elle ne remplace pas totalement les évaluations périodiques."},

{d:5,e:"really-hard",s:"Accepting high residual risk without documenting the decision, owner or monitoring is primarily a failure of:",o:["Technical implementation","Vulnerability scanning","Risk acceptance process and accountability","Incident response speed"],c:2,x:"Une acceptation de risque non documentée et sans responsable est un échec de gouvernance.",r:"Ce n'est pas principalement un problème technique."},
{d:5,e:"really-hard",s:"Which situation best shows a failure in third-party risk management?",o:["Supplier is assessed yearly with strong contract clauses","Supplier provides annual SOC 2 reports","Critical supplier handles sensitive data but has never been assessed and has no security clauses","Supplier is used only for non-sensitive marketing"],c:2,x:"Ne jamais évaluer un fournisseur critique qui traite des données sensibles est un échec majeur.",r:"Des évaluations régulières sont une bonne pratique."},
{d:5,e:"really-hard",s:"Which framework is most widely used in the US for managing cybersecurity risk at organisation level?",o:["ISO 27001 only","COBIT only","NIST Cybersecurity Framework and/or NIST RMF","ITIL only"],c:2,x:"Le NIST CSF et le RMF sont les plus utilisés aux États-Unis pour la gestion du risque cyber organisationnel.",r:"ISO 27001 est important mondialement mais NIST domine aux US."},
{d:5,e:"really-hard",s:"When a new regulation affecting the organisation is published, the most important action is to:",o:["Ignore it until an audit","Inform legal only","Assess impact, identify gaps and plan required changes to policies, processes and controls","Buy a new tool immediately"],c:2,x:"Il faut évaluer l'impact, identifier les écarts et planifier les changements nécessaires.",r:"Ignorer la réglementation est risqué."},
{d:5,e:"really-hard",s:"Why is an accurate inventory of systems and data important?",o:["It increases admin work only","It replaces vulnerability management","It shows what needs protection and supports risk assessment and prioritisation","It removes the need for scanning"],c:2,x:"Un inventaire précis permet de savoir ce qu'il faut protéger et de prioriser les efforts.",r:"Il ne remplace pas la gestion des vulnérabilités."},
{d:5,e:"really-hard",s:"Which statement correctly describes policies, standards and procedures?",o:["They mean the same thing","Procedures are higher level than policies","Policies set direction, standards define mandatory requirements, procedures give step-by-step instructions","Standards are optional while policies are mandatory"],c:2,x:"Les politiques donnent la direction, les standards fixent les exigences, les procédures décrivent les étapes.",r:"Ces termes ne sont pas interchangeables."},
{d:5,e:"really-hard",s:"When a major security incident occurs, governance requires that:",o:["Only the technical team knows","No records are kept","Appropriate stakeholders are informed according to escalation and notification processes","All public communication is avoided"],c:2,x:"Les processus d'escalade et de notification doivent être respectés.",r:"Cacher l'incident n'est pas une bonne pratique."},
{d:5,e:"really-hard",s:"The most important characteristic of a risk owner is that they:",o:["Are always technical experts","Are always SOC members","Have authority and accountability for decisions about that risk","Have no decision power"],c:2,x:"Le propriétaire du risque doit avoir l'autorité et la responsabilité des décisions de traitement.",r:"Ce n'est pas forcément un profil technique."},
{d:5,e:"really-hard",s:"Which activity best demonstrates due diligence in third-party risk management?",o:["Trusting self-attestation only","Checking the supplier website only","Performing assessments, setting contractual security requirements and monitoring compliance","Signing a contract with no security clauses"],c:2,x:"Évaluations, exigences contractuelles et suivi continu démontrent la due diligence.",r:"Se fier uniquement à l'auto-déclaration est insuffisant."},
{d:5,e:"really-hard",s:"A control required by law or regulation is best described as:",o:["Optional best practice","Technical recommendation only","Compliance / regulatory requirement","Contractual preference only"],c:2,x:"Une exigence légale ou réglementaire est obligatoire.",r:"Ce n'est pas une simple recommandation optionnelle."},

{d:5,e:"hard",s:"The main purpose of a security governance framework is to:",o:["Replace technical controls","Eliminate risk assessments","Align security activities with business objectives and risk appetite","Focus only on checklists"],c:2,x:"La gouvernance aligne la sécurité sur les objectifs business et l'appétit pour le risque.",r:"Elle ne remplace pas les contrôles techniques."},
{d:5,e:"hard",s:"When residual risk is accepted, the organisation should also:",o:["Never review it again","Automatically transfer it","Define monitoring and review the acceptance periodically","Ignore related incidents"],c:2,x:"L'acceptation d'un risque doit s'accompagner de monitoring et de revues périodiques.",r:"Ignorer le risque ensuite est dangereux."},
{d:5,e:"hard",s:"Which is the best example of a governance-level security metric?",o:["Raw log volume per day","Number of firewall rules","Percentage of critical systems with tested backups and residual risk trend","Number of antivirus signatures"],c:2,x:"Une métrique de gouvernance relie la couverture de contrôles critiques à l'évolution du risque résiduel.",r:"Le volume de logs n'est pas une métrique de gouvernance."},
{d:5,e:"hard",s:"Which principle prevents the same person from both initiating and approving a critical transaction?",o:["Least privilege","Need to know","Separation of duties","Defense in depth"],c:2,x:"La séparation des tâches empêche qu'une seule personne contrôle tout un processus critique.",r:"Le moindre privilège limite les droits mais ne force pas la dualité."},
{d:5,e:"really-hard",s:"Which approach best reflects mature risk treatment decisions?",o:["Implementing every possible control regardless of cost","Documenting decisions, assigning risk owners and defining monitoring for accepted risks","Keeping acceptance decisions informal","Transferring every risk to insurance without analysis"],c:1,x:"Une approche mature documente les décisions, désigne un propriétaire et définit le suivi.",r:"Tout contrôler sans regarder le coût n'est pas réaliste."},
{d:5,e:"hard",s:"What is the main purpose of a risk register?",o:["Replace security controls","Track identified risks, owners, treatment decisions and status","Increase paperwork only","Eliminate residual risk"],c:1,x:"Le risk register permet de suivre les risques, leurs propriétaires et les décisions de traitement.",r:"Il ne remplace pas les contrôles."},
{d:5,e:"really-hard",s:"In data protection regulations, the principle of accountability requires that organisations:",o:["Collect data only for marketing","Can demonstrate compliance with data protection principles and obligations","Never share data with third parties","Delete all data after 30 days"],c:1,x:"Le principe de responsabilité exige que l'organisation puisse démontrer sa conformité.",r:"Il ne se limite pas à une durée de conservation fixe."},
{d:5,e:"hard",s:"A key output of a Business Impact Analysis is:",o:["List of open ports","Recovery Time Objectives and Recovery Point Objectives for critical processes","Complete firewall rule inventory","Phishing simulation report"],c:1,x:"La BIA produit notamment les RTO et RPO des processus critiques.",r:"Ce n'est pas un scan de ports."},
{d:5,e:"really-hard",s:"Which statement correctly describes inherent risk versus residual risk?",o:["Residual risk is always higher than inherent risk","Inherent risk remains after controls; residual risk exists before controls","Inherent risk exists before controls; residual risk remains after controls","They are the same concept"],c:2,x:"Le risque inhérent existe avant les contrôles ; le risque résiduel reste après.",r:"Les deux termes ne sont pas identiques."},
{d:5,e:"hard",s:"What is the primary reason for assigning a risk owner?",o:["Increase the number of meetings","Have someone accountable for treatment decisions and monitoring of that risk","Replace the risk register","Automatically eliminate the risk"],c:1,x:"Le propriétaire du risque est responsable des décisions de traitement et du suivi.",r:"Il ne supprime pas automatiquement le risque."},

];